  { min: 45, name: 'Mids', color: '#8fcfc2' },
  { min: 0, name: 'Reggie', color: '#9aa79d' }
];
export function gradeFor(q) {
  return QUALITY_GRADES.find(g => q >= g.min) || QUALITY_GRADES[QUALITY_GRADES.length - 1];
