updateFronts(dt) {
  if (!this.state.fronts.length || this.state.dirty <= 0) return;
  const rateMult = this.state.fronts.includes('legal') ? 1.06 : 1;
  const legalBonus = this.state.fronts.includes('legal') ? .03 : 0;
