  heatLabel() {
    const h = this.state.heat;
    if (h >= 85) return 'RAID IMMINENT';
    if (h >= 65) return 'UNDER SURVEILLANCE';
    if (h >= 40) return 'QUESTIONS ASKED';
    if (h >= 20) return 'ON THE RADAR';
    return 'INVISIBLE';
  }

  //__MORE__
}
