:root {
  --bg: #080d0a;
  --panel: #101813;
  --panel2: #16211b;
  --line: rgba(210, 255, 220, .1);
  --line-strong: rgba(210, 255, 220, .18);
  --text: #ecf6ed;
  --muted: #93a698;
  --green: #7bf58a;
  --green2: #3ddc84;
  --acid: #c8ff6e;
  --gold: #ffcf6b;
  --red: #ff7070;
  --cyan: #7ae7ff;
  --purple: #c79bff;
  --font: "Inter", ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  --display: "Arial Black", "Archivo Black", Impact, "Helvetica Neue", sans-serif;
}
* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }
html, body { margin: 0; padding: 0; height: 100%; overflow: hidden; background: var(--bg); color: var(--text); font-family: var(--font); }
body { -webkit-font-smoothing: antialiased; text-rendering: optimizeLegibility; }
button { font-family: var(--font); color: inherit; border: 0; background: none; cursor: pointer; }
button:focus-visible { outline: 2px solid var(--acid); outline-offset: 2px; }
h1, h2, h3, p { margin: 0; }
svg { display: block; }
.sprite { position: absolute; width: 0; height: 0; overflow: hidden; }
.icon { width: 18px; height: 18px; }

#app { position: fixed; inset: 0; overflow: hidden; }
#scene { position: absolute; inset: 0; width: 100%; height: 100%; display: block; touch-action: manipulation; }
.screen-grain {
  position: absolute; inset: 0; pointer-events: none; z-index: 2; opacity: .16;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.4'/%3E%3C/svg%3E");
  mix-blend-mode: overlay;
}

/* ---------------- TOP BAR ---------------- */
.topbar {
  position: absolute; top: 0; left: 0; right: 0; z-index: 20;
  display: flex; align-items: center; gap: 16px; padding: 12px 18px 22px;
  pointer-events: none;
  background: linear-gradient(to bottom, rgba(5,9,7,.88) 0%, rgba(5,9,7,.55) 55%, rgba(5,9,7,0) 100%);
}
.topbar > * { pointer-events: auto; }
.brand { display: flex; align-items: center; gap: 10px; flex: 0 0 auto; }
.brand-mark { width: 38px; height: 38px; color: var(--acid); filter: drop-shadow(0 0 12px rgba(180,255,100,.3)); }
.brand-mark svg { width: 100%; height: 100%; }
.brand-title { font-family: var(--display); font-size: 18px; line-height: .95; letter-spacing: .4px; font-weight: 900; }
.brand-title span { color: var(--acid); }
.brand-sub { font-size: 7px; letter-spacing: 2.8px; color: var(--muted); margin-top: 4px; font-weight: 700; }

.stats { display: flex; align-items: stretch; gap: 6px; margin-left: auto; }
.stat {
  display: flex; align-items: center; gap: 8px; min-width: 88px; padding: 6px 10px 6px 7px;
  background: rgba(9,16,12,.72); border: 1px solid var(--line); border-radius: 12px;
  backdrop-filter: blur(14px); -webkit-backdrop-filter: blur(14px); text-align: left;
  transition: border-color .2s, background .2s, transform .15s;
}
.stat:hover { border-color: rgba(150,255,160,.35); background: rgba(16,28,20,.85); }
.stat:active { transform: scale(.98); }
.stat-icon { width: 27px; height: 27px; border-radius: 8px; display: grid; place-items: center; background: rgba(160,255,170,.08); color: var(--green); flex: 0 0 auto; }
.stat-icon svg { width: 15px; height: 15px; }
.stat-body { display: flex; flex-direction: column; gap: 1px; min-width: 0; }
.stat-label { font-size: 7px; letter-spacing: 1.5px; color: var(--muted); font-weight: 800; }
.stat-value { font-size: 12.5px; font-weight: 800; line-height: 1.1; white-space: nowrap; }
.stat-sub { font-size: 8.5px; color: var(--muted); white-space: nowrap; }
.stat-money .stat-value { color: var(--gold); }
.stat-money .stat-sub { color: var(--green); opacity: .9; }
.stat-heat .stat-icon { color: var(--red); background: rgba(255,100,100,.08); }
.stat-heat .stat-value { color: #ffb4a8; }
.heat-bar { display: block; width: 62px; height: 3px; border-radius: 3px; background: rgba(255,255,255,.11); margin-top: 3px; overflow: hidden; }
.heat-bar i { display: block; height: 100%; width: 0%; border-radius: 3px; background: linear-gradient(90deg, var(--green), var(--gold), var(--red)); transition: width .4s; }
.stat-rep .stat-icon { color: var(--purple); background: rgba(199,155,255,.09); }
.stat-day .stat-icon { color: var(--cyan); background: rgba(122,231,255,.08); }
.top-actions { display: flex; gap: 6px; flex: 0 0 auto; }
.icon-btn {
  width: 34px; height: 34px; border-radius: 10px; display: grid; place-items: center;
  background: rgba(9,16,12,.7); border: 1px solid var(--line); color: var(--muted);
  backdrop-filter: blur(12px); transition: .2s;
}
.icon-btn svg { width: 16px; height: 16px; }
.icon-btn:hover { color: var(--text); border-color: var(--line-strong); background: rgba(20,32,24,.9); }

/* ---------------- MISSION STRIP ---------------- */
.mission-strip {
  position: absolute; top: 82px; left: 18px; z-index: 16;
  display: flex; align-items: center; gap: 9px; padding: 7px 10px 7px 12px;
  background: rgba(9,16,12,.76); border: 1px solid var(--line); border-radius: 11px;
  backdrop-filter: blur(14px); text-align: left; max-width: min(620px, calc(100vw - 36px));
  transition: border-color .2s, transform .15s; overflow: hidden;
}
.mission-strip:hover { border-color: rgba(200,255,110,.4); transform: translateY(-1px); }
.mission-kicker { font-size: 7px; letter-spacing: 1.8px; font-weight: 800; color: var(--acid); white-space: nowrap; }
.mission-title { font-size: 10.5px; font-weight: 800; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mission-prog { width: 50px; height: 3px; border-radius: 2px; background: rgba(255,255,255,.1); overflow: hidden; flex: 0 0 auto; }
.mission-prog i { display: block; height: 100%; width: 0%; background: var(--acid); transition: width .4s; }
.mission-obj { font-size: 8.5px; color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mission-go { font-size: 8px; letter-spacing: 1px; font-weight: 800; color: var(--green); display: flex; align-items: center; gap: 3px; margin-left: 3px; white-space: nowrap; }
.mission-go svg { width: 10px; height: 10px; }
.mission-strip.ready { border-color: rgba(200,255,110,.55); box-shadow: 0 0 24px rgba(160,255,100,.14); }
.mission-strip.ready .mission-kicker { color: #fff; }

/* ---------------- HINT ---------------- */
.hint {
  position: absolute; left: 50%; bottom: 98px; transform: translateX(-50%); z-index: 16;
  display: flex; align-items: center; gap: 8px; padding: 7px 13px;
  background: rgba(9,16,12,.8); border: 1px solid var(--line); border-radius: 100px;
  font-size: 10px; color: #c9d8cb; white-space: nowrap; max-width: calc(100vw - 28px);
  backdrop-filter: blur(14px); transition: opacity .3s, transform .3s; pointer-events: none;
  overflow: hidden; text-overflow: ellipsis;
}
.hint.hidden { opacity: 0; transform: translate(-50%, 8px); }
.hint-dot { width: 6px; height: 6px; border-radius: 50%; background: var(--acid); box-shadow: 0 0 10px var(--acid); flex: 0 0 auto; animation: dotPulse 2s infinite; }
@keyframes dotPulse { 0%,100% { opacity: 1; transform: scale(1); } 50% { opacity: .35; transform: scale(.7); } }

/* ---------------- DOCK ---------------- */
.dock {
  position: absolute; left: 50%; bottom: 12px; transform: translateX(-50%); z-index: 22;
  display: flex; gap: 3px; padding: 5px;
  background: rgba(7,13,10,.88); border: 1px solid rgba(210,255,220,.12); border-radius: 17px;
  backdrop-filter: blur(22px); -webkit-backdrop-filter: blur(22px);
  box-shadow: 0 14px 45px rgba(0,0,0,.55), inset 0 1px 0 rgba(255,255,255,.05);
}
.dock-btn {
  position: relative; width: 74px; height: 58px; border-radius: 12px;
  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 4px;
  color: var(--muted); transition: background .18s, color .18s, transform .12s;
}
.dock-btn:hover { background: rgba(255,255,255,.055); color: var(--text); }
.dock-btn:active { transform: scale(.95); }
.dock-btn.active { background: rgba(160,255,140,.11); color: var(--acid); }
.dock-ico { width: 22px; height: 22px; display: grid; place-items: center; }
.dock-ico svg { width: 21px; height: 21px; }
.dock-label { font-size: 7.5px; font-weight: 800; letter-spacing: 1.1px; }
.dock-key { position: absolute; top: 4px; right: 5px; font-size: 6px; color: rgba(200,220,205,.35); font-weight: 700; }
.dock-badge { position: absolute; top: 9px; right: 15px; width: 6px; height: 6px; border-radius: 50%; background: var(--red); box-shadow: 0 0 8px var(--red); display: none; }
.dock-badge.show { display: block; animation: dotPulse 1.5s infinite; }
.dock-story.active .dock-ico { color: var(--acid); }

/* ---------------- SCENE TIP ---------------- */
.scene-tip {
  position: absolute; z-index: 24; pointer-events: none; padding: 5px 9px;
  background: rgba(7,13,10,.94); border: 1px solid rgba(190,255,180,.25); border-radius: 7px;
  font-size: 9.5px; font-weight: 600; color: #e6f7e6; white-space: nowrap;
  transform: translate(-50%, -130%); opacity: 0; transition: opacity .12s;
  box-shadow: 0 6px 20px rgba(0,0,0,.5);
}
.scene-tip.show { opacity: 1; }

/* ---------------- TOASTS ---------------- */
.toasts { position: absolute; top: 84px; right: 16px; z-index: 50; display: flex; flex-direction: column; gap: 6px; align-items: flex-end; pointer-events: none; max-width: min(340px, calc(100vw - 24px)); }
.toast {
  display: flex; align-items: flex-start; gap: 8px; padding: 8px 12px;
  background: rgba(10,18,14,.96); border: 1px solid var(--line); border-left: 3px solid var(--green);
  border-radius: 9px; font-size: 10.5px; line-height: 1.35; color: #dcecdf; box-shadow: 0 8px 30px rgba(0,0,0,.5);
  animation: toastIn .25s ease both; backdrop-filter: blur(10px); max-width: 100%;
}
.toast.bad { border-left-color: var(--red); }
.toast.warn { border-left-color: var(--gold); }
.toast.good { border-left-color: var(--green); }
.toast.info { border-left-color: var(--cyan); }
.toast.out { animation: toastOut .3s ease both; }
@keyframes toastIn { from { opacity: 0; transform: translateX(18px); } to { opacity: 1; transform: translateX(0); } }
@keyframes toastOut { to { opacity: 0; transform: translateX(20px); } }

/* ---------------- PANEL ---------------- */
.panel-backdrop {
  position: absolute; inset: 0; z-index: 30; background: rgba(2,5,4,.45);
  opacity: 0; visibility: hidden; transition: .25s; backdrop-filter: blur(2px);
}
.panel-backdrop.open { opacity: 1; visibility: visible; }
.panel {
  position: absolute; top: 84px; right: 14px; bottom: 88px; width: 432px; max-width: calc(100vw - 28px); z-index: 35;
  display: flex; flex-direction: column; overflow: hidden;
  background: linear-gradient(155deg, rgba(20,31,25,.985), rgba(9,15,12,.99));
  border: 1px solid rgba(190,255,200,.13); border-radius: 20px;
  box-shadow: 0 30px 80px rgba(0,0,0,.65), inset 0 1px 0 rgba(255,255,255,.04);
  transform: translateX(calc(100% + 30px)); transition: transform .3s cubic-bezier(.22,1,.36,1);
}
.panel.open { transform: translateX(0); }
.panel-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 10px; padding: 18px 18px 13px; border-bottom: 1px solid var(--line); background: rgba(255,255,255,.012); flex: 0 0 auto; }
.panel-kicker { font-size: 7.5px; letter-spacing: 2.3px; color: var(--acid); font-weight: 800; margin-bottom: 4px; }
.panel-head h2 { font-size: 19px; font-weight: 900; letter-spacing: -.2px; }
.panel-head p { font-size: 10px; color: var(--muted); margin-top: 4px; line-height: 1.35; max-width: 300px; }
.panel-close { flex: 0 0 auto; }
.panel-body { padding: 14px 16px 26px; overflow-y: auto; overscroll-behavior: contain; scrollbar-width: thin; scrollbar-color: rgba(150,255,160,.25) transparent; }
.panel-body::-webkit-scrollbar { width: 5px; }
.panel-body::-webkit-scrollbar-thumb { background: rgba(150,255,160,.22); border-radius: 5px; }

.sec-title { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin: 16px 0 8px; font-size: 8px; letter-spacing: 1.6px; font-weight: 800; color: var(--muted); text-transform: uppercase; }
.sec-title:first-child { margin-top: 2px; }
.sec-title em { font-style: normal; color: rgba(200,220,205,.5); font-weight: 600; letter-spacing: .4px; font-size: 8.5px; text-transform: none; }
.card { background: rgba(255,255,255,.032); border: 1px solid var(--line); border-radius: 13px; padding: 11px 12px; margin-bottom: 8px; }
.muted { color: var(--muted); }
.tiny { font-size: 9px; line-height: 1.4; }
.small { font-size: 10px; }
.gold { color: var(--gold); }
.green { color: var(--green); }
.acid { color: var(--acid); }
.red { color: var(--red); }
.cyan { color: var(--cyan); }
.purple { color: var(--purple); }
.row { display: flex; align-items: center; gap: 8px; }
.between { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.grow { flex: 1; }
.chip { display: inline-flex; align-items: center; gap: 4px; padding: 2px 6px; border-radius: 5px; background: rgba(255,255,255,.05); border: 1px solid var(--line); font-size: 8px; font-weight: 700; color: #c7d5c8; white-space: nowrap; }
.chip.green { background: rgba(120,245,140,.08); border-color: rgba(120,245,140,.18); color: var(--green); }
.chip.gold { background: rgba(255,207,107,.08); border-color: rgba(255,207,107,.18); color: var(--gold); }
.chip.red { background: rgba(255,112,112,.08); border-color: rgba(255,112,112,.2); color: var(--red); }
.chip.purple { background: rgba(199,155,255,.08); border-color: rgba(199,155,255,.2); color: var(--purple); }
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 6px;
  padding: 8px 13px; min-height: 32px; border-radius: 8px; background: linear-gradient(160deg, var(--acid), #7bdc69);
  color: #0b150c; font-size: 9.5px; font-weight: 900; letter-spacing: .6px; text-transform: uppercase;
  transition: transform .12s, filter .15s, opacity .2s; border: 0;
}
.btn:hover { filter: brightness(1.08); }
.btn:active { transform: scale(.97); }
.btn:disabled { opacity: .35; cursor: not-allowed; filter: grayscale(.4); }
.btn.ghost { background: rgba(255,255,255,.045); color: var(--text); border: 1px solid var(--line-strong); }
.btn.ghost:hover { background: rgba(255,255,255,.08); }
.btn.danger { background: linear-gradient(160deg, #ff7c6f, #cc3f46); color: #1a0607; }
.btn.small { min-height: 26px; padding: 5px 9px; font-size: 8.5px; border-radius: 7px; }
.btn.wide { width: 100%; }
.btn .ico { width: 14px; height: 14px; display: inline-flex; }
.btn .ico svg { width: 14px; height: 14px; }
.btn-row { display: flex; gap: 6px; flex-wrap: wrap; }

.strain-card { position: relative; display: flex; gap: 10px; padding: 10px; border-radius: 12px; border: 1px solid var(--line); background: rgba(255,255,255,.025); margin-bottom: 7px; cursor: pointer; transition: .18s; overflow: hidden; }
.strain-card:hover { border-color: rgba(180,255,180,.28); background: rgba(255,255,255,.045); }
.strain-card.active { border-color: rgba(200,255,110,.55); background: rgba(200,255,110,.055); }
.strain-card.locked { opacity: .46; cursor: not-allowed; }
.strain-swatch { width: 4px; border-radius: 3px; flex: 0 0 auto; align-self: stretch; }
.strain-main { flex: 1; min-width: 0; }
.strain-name { font-size: 11.5px; font-weight: 800; display: flex; align-items: center; gap: 6px; }
.strain-desc { font-size: 8.5px; color: var(--muted); line-height: 1.35; margin-top: 2px; }
.strain-stats { display: flex; gap: 5px; flex-wrap: wrap; margin-top: 6px; }
.strain-side { display: flex; flex-direction: column; align-items: flex-end; gap: 4px; justify-content: center; }
.strain-cost { font-size: 11px; font-weight: 800; color: var(--gold); white-space: nowrap; }
.strain-lock { font-size: 7px; color: var(--muted); letter-spacing: .4px; }

.inv-row { display: flex; align-items: center; gap: 8px; padding: 7px 0; border-bottom: 1px solid rgba(255,255,255,.05); }
.inv-row:last-child { border-bottom: 0; }
.dot { width: 8px; height: 8px; border-radius: 50%; flex: 0 0 auto; }
.bar { height: 4px; border-radius: 3px; background: rgba(255,255,255,.09); overflow: hidden; }
.bar i { display: block; height: 100%; border-radius: 3px; background: var(--green); transition: width .4s; }

.price-grid { display: grid; grid-template-columns: repeat(3,1fr); gap: 5px; }
.price-opt { padding: 8px 5px; border: 1px solid var(--line); border-radius: 9px; background: rgba(255,255,255,.025); text-align: center; font-size: 8.5px; line-height: 1.3; transition: .15s; color: var(--muted); }
.price-opt:hover { border-color: var(--line-strong); }
.price-opt.active { border-color: rgba(200,255,110,.5); background: rgba(200,255,110,.06); color: var(--text); }
.price-opt b { display: block; font-size: 9.5px; margin-bottom: 1px; color: var(--text); }
.price-opt span { display: block; font-size: 7.5px; margin-top: 2px; }

.staff-card { display: flex; gap: 10px; align-items: center; }
.avatar { width: 38px; height: 38px; border-radius: 50%; display: grid; place-items: center; font-weight: 900; font-size: 12px; color: #08110a; flex: 0 0 auto; border: 2px solid rgba(255,255,255,.15); }
.role { font-size: 8px; letter-spacing: 1px; text-transform: uppercase; color: var(--muted); font-weight: 800; }
.staff-info { flex: 1; min-width: 0; }
.staff-name { font-size: 11.5px; font-weight: 800; }
.staff-desc { font-size: 8.5px; color: var(--muted); line-height: 1.35; margin-top: 2px; }
.wage { font-size: 8px; color: var(--gold); }

.upg-card { display: flex; align-items: center; gap: 10px; }
.upg-icon { width: 32px; height: 32px; border-radius: 9px; display: grid; place-items: center; background: rgba(160,255,170,.06); color: var(--green); flex: 0 0 auto; }
.upg-icon svg { width: 17px; height: 17px; }
.pips { display: flex; gap: 3px; margin-top: 4px; }
.pips i { width: 10px; height: 3px; border-radius: 2px; background: rgba(255,255,255,.1); }
.pips i.on { background: var(--green); box-shadow: 0 0 5px rgba(120,245,140,.4); }

.prop-card { position: relative; overflow: hidden; padding: 0; }
.prop-visual { height: 70px; display: flex; align-items: flex-end; padding: 10px 12px; position: relative; }
.prop-visual::after { content: ''; position: absolute; inset: 0; background: linear-gradient(to top, rgba(10,16,13,.9), transparent); }
.prop-visual .tags { position: relative; z-index: 1; display: flex; gap: 4px; }
.prop-body { padding: 9px 12px 11px; }
.prop-title { font-size: 12px; font-weight: 800; }
.prop-sub { font-size: 8.5px; color: var(--muted); line-height: 1.35; margin-top: 2px; }
.prop-stats { display: flex; gap: 4px; flex-wrap: wrap; margin: 7px 0; }
.prop-foot { display: flex; align-items: center; justify-content: space-between; gap: 8px; }

.front-card { display: flex; gap: 10px; align-items: center; }
.front-icon { width: 36px; height: 36px; border-radius: 10px; display: grid; place-items: center; font-size: 16px; flex: 0 0 auto; background: rgba(255,255,255,.05); border: 1px solid var(--line); }

.laundry-hero { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 14px; border-radius: 14px; background: radial-gradient(circle at 20% 10%, rgba(120,245,140,.09), rgba(255,255,255,.025)); border: 1px solid var(--line); margin-bottom: 10px; }
.laundry-money { font-size: 22px; font-weight: 900; letter-spacing: -.5px; }
.laundry-money.clean { color: var(--green); }
.laundry-money.dirty { color: var(--gold); }
.mini-label { font-size: 7px; letter-spacing: 1.5px; color: var(--muted); font-weight: 800; margin-bottom: 2px; }
.swap-arrow { color: var(--muted); opacity: .5; }
.heat-gauge { height: 12px; border-radius: 8px; background: rgba(255,255,255,.08); overflow: hidden; position: relative; margin: 10px 0 6px; }
.heat-gauge i { display: block; height: 100%; border-radius: 8px; background: linear-gradient(90deg, #4cd982, #ffd166 55%, #ff6b6b); transition: width .4s; }
.heat-scale { display: flex; justify-content: space-between; font-size: 7px; color: var(--muted); letter-spacing: .5px; }

.toggle { width: 36px; height: 20px; border-radius: 20px; background: rgba(255,255,255,.12); position: relative; transition: .2s; flex: 0 0 auto; }
.toggle::after { content: ''; position: absolute; top: 3px; left: 3px; width: 14px; height: 14px; border-radius: 50%; background: #c9d8cb; transition: .2s; }
.toggle.on { background: rgba(120,245,140,.32); }
.toggle.on::after { left: 19px; background: var(--green); }

.empty { text-align: center; padding: 18px 10px; color: var(--muted); font-size: 10px; line-height: 1.5; }
.empty svg { width: 26px; height: 26px; margin: 0 auto 6px; opacity: .4; }

/* ---------------- MODALS ---------------- */
.modal-root {
  position: absolute; inset: 0; z-index: 60; display: flex; align-items: center; justify-content: center;
  padding: 16px; background: rgba(2,5,4,.72); backdrop-filter: blur(9px);
  opacity: 0; visibility: hidden; transition: opacity .25s, visibility .25s;
}
.modal-root.open { opacity: 1; visibility: visible; }
.modal-inner { transform: translateY(16px) scale(.98); transition: transform .3s cubic-bezier(.22,1,.36,1); width: 100%; max-width: 880px; max-height: 92vh; display: flex; justify-content: center; }
.modal-root.open .modal-inner { transform: translateY(0) scale(1); }

.story-card {
  position: relative; width: 100%; max-width: 860px; max-height: 90vh; display: grid; grid-template-columns: 290px 1fr;
  background: linear-gradient(150deg, #15221b 0%, #0a110d 58%); border: 1px solid rgba(190,255,190,.14);
  border-radius: 22px; overflow: hidden; box-shadow: 0 40px 100px rgba(0,0,0,.7);
}
.story-portrait { position: relative; background: radial-gradient(circle at 50% 28%, #24392b, #0a130e 70%); border-right: 1px solid var(--line); min-height: 380px; overflow: hidden; }
.story-portrait canvas { width: 100%; height: 100%; display: block; object-fit: cover; }
.portrait-vignette { position: absolute; inset: 0; background: linear-gradient(to top, rgba(8,14,10,.85), transparent 55%); pointer-events: none; }
.portrait-name { position: absolute; left: 16px; bottom: 16px; right: 16px; z-index: 1; }
.portrait-name b { display: block; font-size: 14px; font-weight: 900; }
.portrait-name span { display: block; font-size: 8px; letter-spacing: 1.7px; text-transform: uppercase; color: var(--muted); margin-top: 3px; }
.story-main { display: flex; flex-direction: column; padding: 22px 24px 18px; min-height: 380px; position: relative; }
.story-top { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding-right: 30px; }
.story-act { font-size: 7.5px; letter-spacing: 2.2px; color: var(--acid); font-weight: 900; }
.story-place { font-size: 8.5px; color: var(--muted); margin-top: 3px; }
.story-title { font-size: 19px; font-weight: 900; margin-top: 10px; letter-spacing: -.2px; }
.story-dialogue { flex: 1; padding: 18px 0 10px; min-height: 160px; display: flex; flex-direction: column; justify-content: center; }
.story-speaker { font-size: 8px; letter-spacing: 1.6px; color: var(--green); font-weight: 900; text-transform: uppercase; margin-bottom: 7px; display: flex; align-items: center; gap: 6px; }
.story-speaker::before { content: ''; width: 16px; height: 1px; background: var(--green); display: block; opacity: .5; }
.story-text { font-size: 16.5px; line-height: 1.55; color: #e5f0e6; font-weight: 500; letter-spacing: -.1px; min-height: 78px; }
.story-text.narrator { font-style: italic; color: #c6d6c7; font-weight: 400; }
.story-text .cursor { display: inline-block; width: 6px; height: 15px; background: var(--acid); margin-left: 2px; vertical-align: -2px; animation: blink .8s infinite; }
@keyframes blink { 50% { opacity: 0; } }
.story-foot { display: flex; align-items: center; justify-content: space-between; gap: 10px; border-top: 1px solid var(--line); padding-top: 12px; }
.story-dots { display: flex; gap: 4px; }
.story-dots i { width: 5px; height: 5px; border-radius: 50%; background: rgba(255,255,255,.16); transition: .2s; }
.story-dots i.on { background: var(--acid); box-shadow: 0 0 6px rgba(200,255,110,.5); }
.story-next { display: flex; align-items: center; gap: 6px; font-size: 8px; letter-spacing: 1.4px; color: var(--muted); font-weight: 800; }
.story-next svg { width: 12px; height: 12px; animation: nudge 1.5s infinite; }
@keyframes nudge { 50% { transform: translateX(4px); } }
.story-close { position: absolute; top: 12px; right: 12px; z-index: 3; }
.story-choice { display: flex; flex-direction: column; gap: 7px; margin-top: 8px; }
.choice-btn { text-align: left; padding: 10px 13px; border-radius: 10px; border: 1px solid rgba(190,255,190,.2); background: rgba(200,255,110,.05); transition: .15s; }
.choice-btn:hover { background: rgba(200,255,110,.11); border-color: rgba(200,255,110,.45); transform: translateX(2px); }
.choice-btn b { display: block; font-size: 11px; font-weight: 800; }
.choice-btn span { display: block; font-size: 8.5px; color: var(--muted); margin-top: 2px; }
.choice-prompt { font-size: 9px; color: var(--muted); margin-bottom: 2px; }

.objective-card { border: 1px solid var(--line); background: rgba(255,255,255,.03); border-radius: 12px; padding: 12px; margin-top: 10px; }
.objective-top { display: flex; justify-content: space-between; gap: 8px; font-size: 9px; color: var(--muted); font-weight: 700; }
.objective-label { font-size: 11px; font-weight: 800; margin: 5px 0 8px; }
.reward-row { display: flex; gap: 5px; flex-wrap: wrap; margin-top: 9px; }
.story-actions { display: flex; gap: 7px; margin-top: 12px; align-items: center; }
.story-actions .btn { flex: 1; }
.story-replay { font-size: 8px; color: var(--muted); text-decoration: underline; background: none; padding: 5px; }

/* Event modal */
.event-card { position: relative; width: 100%; max-width: 500px; background: linear-gradient(160deg, #17241c, #0a110d); border: 1px solid rgba(190,255,190,.16); border-radius: 20px; padding: 22px; box-shadow: 0 30px 80px rgba(0,0,0,.7); overflow: hidden; }
.event-card::before { content: ''; position: absolute; inset: 0; background: radial-gradient(circle at 85% 0%, rgba(200,255,110,.1), transparent 45%); pointer-events: none; }
.event-tag { font-size: 7px; letter-spacing: 2px; color: var(--gold); font-weight: 900; display: flex; align-items: center; gap: 6px; }
.event-icon { width: 42px; height: 42px; border-radius: 12px; background: rgba(200,255,110,.08); border: 1px solid rgba(200,255,110,.18); color: var(--acid); display: grid; place-items: center; margin-bottom: 14px; }
.event-icon svg { width: 22px; height: 22px; }
.event-title { font-size: 21px; font-weight: 900; letter-spacing: -.3px; margin-bottom: 7px; }
.event-body { font-size: 12px; line-height: 1.6; color: #c8d8ca; margin-bottom: 16px; }
.event-choices { display: flex; flex-direction: column; gap: 7px; }
.event-result { font-size: 12px; line-height: 1.6; color: #dcebde; border-left: 2px solid var(--acid); padding-left: 10px; margin: 12px 0; }

/* Raid modal */
.raid-card { width: 100%; max-width: 520px; background: radial-gradient(circle at 50% 0%, rgba(255,60,60,.18), transparent 45%), linear-gradient(160deg, #1d1313, #0b0d0c); border: 1px solid rgba(255,100,100,.3); border-radius: 20px; padding: 24px; text-align: center; box-shadow: 0 0 80px rgba(255,40,40,.18), 0 30px 80px rgba(0,0,0,.8); animation: raidShake .5s ease; }
@keyframes raidShake { 0%,100% { transform: translateX(0); } 20% { transform: translateX(-6px); } 40% { transform: translateX(5px); } 60% { transform: translateX(-3px); } 80% { transform: translateX(2px); } }
.siren-ico { width: 54px; height: 54px; margin: 0 auto 10px; color: #ff8b8b; filter: drop-shadow(0 0 16px rgba(255,70,70,.4)); animation: sirenPulse 1s infinite; }
.siren-ico svg { width: 100%; height: 100%; }
@keyframes sirenPulse { 50% { color: #7db4ff; filter: drop-shadow(0 0 20px rgba(100,160,255,.5)); } }
.raid-kicker { font-size: 8px; letter-spacing: 3px; color: #ff9d9d; font-weight: 900; }
.raid-title { font-size: 36px; font-weight: 900; letter-spacing: -1px; margin: 5px 0 4px; line-height: .95; }
.raid-sub { font-size: 11px; color: #d3b8b8; line-height: 1.5; margin-bottom: 16px; }
.loss-grid { display: grid; grid-template-columns: repeat(3,1fr); gap: 6px; margin: 14px 0 18px; }
.loss { background: rgba(255,255,255,.04); border: 1px solid rgba(255,100,100,.16); border-radius: 9px; padding: 8px 4px; }
.loss b { display: block; font-size: 14px; color: #ff9f9f; }
.loss span { font-size: 7px; letter-spacing: 1px; color: var(--muted); text-transform: uppercase; }

/* ending */
.ending-card { width: 100%; max-width: 620px; background: radial-gradient(circle at 50% -20%, rgba(200,255,110,.18), transparent 55%), linear-gradient(160deg, #16241a, #080d0a); border: 1px solid rgba(200,255,110,.25); border-radius: 22px; padding: 30px; text-align: center; box-shadow: 0 0 100px rgba(160,255,100,.1), 0 40px 100px rgba(0,0,0,.8); max-height: 90vh; overflow-y: auto; }
.ending-kicker { font-size: 8px; letter-spacing: 3px; color: var(--acid); font-weight: 900; }
.ending-title { font-family: var(--display); font-size: 44px; line-height: .9; margin: 10px 0; letter-spacing: -1px; }
.ending-title span { color: var(--acid); }
.ending-text { font-size: 12px; line-height: 1.7; color: #c7d8c9; max-width: 450px; margin: 0 auto 18px; }
.ending-stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: 6px; margin: 16px 0 20px; }
.ending-stats div { background: rgba(255,255,255,.035); border: 1px solid var(--line); border-radius: 9px; padding: 9px 4px; }
.ending-stats b { display: block; font-size: 13px; color: var(--acid); }
.ending-stats span { font-size: 6.5px; letter-spacing: 1px; color: var(--muted); text-transform: uppercase; }

/* refine */
.refine-card { width: 100%; max-width: 540px; background: linear-gradient(160deg, #131f1a, #080f0b); border: 1px solid rgba(110,231,255,.2); border-radius: 20px; padding: 22px; box-shadow: 0 30px 80px rgba(0,0,0,.75); }
.refine-top { display: flex; justify-content: space-between; align-items: flex-start; gap: 10px; }
.refine-title { font-size: 19px; font-weight: 900; }
.refine-body { font-size: 10px; color: var(--muted); line-height: 1.5; margin: 4px 0 16px; }
.chem-meter { position: relative; height: 54px; border-radius: 10px; background: linear-gradient(90deg, rgba(255,90,90,.2), rgba(120,245,140,.15) 30%, rgba(120,245,140,.15) 70%, rgba(255,90,90,.2)); border: 1px solid var(--line); overflow: hidden; margin: 8px 0 10px; }
.chem-zone { position: absolute; top: 0; bottom: 0; background: rgba(120,245,140,.13); border-left: 1px solid rgba(120,245,140,.35); border-right: 1px solid rgba(120,245,140,.35); }
.chem-zone.core { background: rgba(200,255,110,.24); border-color: rgba(200,255,110,.6); }
.chem-needle { position: absolute; top: -4px; bottom: -4px; width: 3px; background: var(--acid); box-shadow: 0 0 14px var(--acid); border-radius: 2px; }
.chem-ticks { position: absolute; inset: 0; display: flex; justify-content: space-between; padding: 4px; pointer-events: none; }
.chem-ticks i { width: 1px; height: 6px; background: rgba(255,255,255,.12); }
.chem-readout { display: flex; justify-content: space-between; font-size: 8px; color: var(--muted); letter-spacing: 1px; }
.chem-readout b { color: var(--cyan); }
.refine-actions { display: flex; gap: 6px; margin-top: 14px; }
.refine-actions .btn { flex: 1; }
.refine-note { font-size: 8.5px; color: var(--muted); margin-top: 8px; line-height: 1.4; }
.refine-result { text-align: center; padding: 18px 4px 8px; }
.refine-result .big { font-size: 34px; font-weight: 900; color: var(--acid); line-height: 1; }
.refine-result p { font-size: 11px; color: var(--muted); margin: 6px 0 14px; }

/* offline */
.offline-card { width: 100%; max-width: 460px; background: linear-gradient(160deg, #15221b, #0a110d); border: 1px solid var(--line); border-radius: 20px; padding: 24px; box-shadow: 0 30px 80px rgba(0,0,0,.7); }
.offline-card h2 { font-size: 21px; font-weight: 900; margin-bottom: 4px; }
.offline-card p { font-size: 11px; color: var(--muted); line-height: 1.5; }
.offline-grid { display: grid; grid-template-columns: repeat(3,1fr); gap: 6px; margin: 16px 0; }
.offline-grid div { background: rgba(255,255,255,.035); border: 1px solid var(--line); border-radius: 9px; padding: 9px 4px; text-align: center; }
.offline-grid b { display: block; font-size: 14px; color: var(--acid); }
.offline-grid span { font-size: 7px; letter-spacing: 1px; color: var(--muted); text-transform: uppercase; }

/* ---------------- SPLASH ---------------- */
.splash { position: absolute; inset: 0; z-index: 100; display: flex; align-items: center; justify-content: center; overflow: hidden; background: radial-gradient(circle at 50% 110%, #24381f 0%, #0b120d 42%, #060907 100%); transition: opacity .5s, visibility .5s; }
.splash.hidden { opacity: 0; visibility: hidden; pointer-events: none; }
.splash-glow { position: absolute; width: 900px; height: 900px; left: 50%; bottom: -600px; transform: translateX(-50%); background: radial-gradient(circle, rgba(150,255,90,.28), rgba(60,160,80,.1) 38%, transparent 65%); filter: blur(20px); animation: glowPulse 7s infinite; }
@keyframes glowPulse { 50% { opacity: .65; transform: translateX(-50%) scale(1.08); } }
.splash-grid { position: absolute; left: -20%; right: -20%; bottom: -10%; height: 65%; background-image: linear-gradient(rgba(150,255,140,.08) 1px, transparent 1px), linear-gradient(90deg, rgba(150,255,140,.08) 1px, transparent 1px); background-size: 54px 54px; transform: perspective(400px) rotateX(62deg); transform-origin: bottom; mask-image: linear-gradient(to top, rgba(0,0,0,.8), transparent 80%); -webkit-mask-image: linear-gradient(to top, rgba(0,0,0,.8), transparent 80%); opacity: .55; }
.splash-card { position: relative; z-index: 2; text-align: center; display: flex; flex-direction: column; align-items: center; max-width: 660px; padding: 30px 24px; animation: splashIn .9s cubic-bezier(.22,1,.36,1) both; }
@keyframes splashIn { from { opacity: 0; transform: translateY(18px); } }
.splash-season { font-size: 8px; letter-spacing: 5px; color: rgba(200,255,140,.65); font-weight: 800; margin-bottom: 18px; }
.splash-emblem { width: 62px; height: 62px; color: var(--acid); margin-bottom: 6px; filter: drop-shadow(0 0 22px rgba(180,255,100,.4)); }
.splash-emblem svg { width: 100%; height: 100%; }
.splash-title { font-family: var(--display); font-weight: 900; font-size: clamp(54px, 10vw, 104px); line-height: .8; letter-spacing: -4px; margin: 2px 0 18px; text-transform: uppercase; }
.splash-title span { display: block; }
.splash-title span:first-child { color: #eef9e8; text-shadow: 0 4px 0 rgba(0,0,0,.3); }
.splash-title span:last-child { color: var(--acid); text-shadow: 0 0 40px rgba(180,255,100,.25), 0 5px 0 rgba(20,50,20,.6); letter-spacing: 2px; }
.splash-tag { font-size: 15px; color: #d6e6d7; letter-spacing: .5px; margin-bottom: 12px; font-weight: 500; }
.splash-tag em { color: var(--gold); font-style: normal; font-weight: 800; }
.splash-blurb { font-size: 11px; line-height: 1.6; color: #8fa493; max-width: 430px; margin-bottom: 24px; }
.splash-btn { display: flex; align-items: center; gap: 10px; padding: 14px 26px; border-radius: 12px; background: linear-gradient(160deg, var(--acid), #7fe06d); color: #0a160c; font-size: 11px; font-weight: 900; letter-spacing: 2px; box-shadow: 0 10px 40px rgba(140,255,100,.22), inset 0 1px 0 rgba(255,255,255,.3); transition: transform .18s, box-shadow .18s; }
.splash-btn:hover { transform: translateY(-2px); box-shadow: 0 14px 50px rgba(140,255,100,.3); }
.splash-btn svg { width: 17px; height: 17px; }
.splash-meta { display: flex; gap: 10px; margin-top: 20px; font-size: 7px; letter-spacing: 2px; color: rgba(170,190,175,.45); font-weight: 700; }
.splash-disclaimer { margin-top: 12px; font-size: 8px; color: rgba(150,170,155,.4); }
.splash-credit { position: absolute; bottom: 16px; left: 0; right: 0; text-align: center; font-size: 7.5px; letter-spacing: 1.4px; color: rgba(140,160,145,.32); text-transform: uppercase; }

/* ---------------- RESPONSIVE ---------------- */
@media (max-width: 1120px) {
  .stat-rep { display: none; }
  .topbar { gap: 10px; }
}
@media (max-width: 900px) {
  .stat-day { display: none; }
  .mission-strip { top: 78px; }
  .dock-btn { width: 68px; }
}
@media (max-width: 720px) {
  .topbar { padding: 8px 8px 12px; gap: 8px; flex-wrap: wrap; }
  .brand-mark { width: 30px; height: 30px; }
  .brand-title { font-size: 14px; }
  .brand-sub { display: none; }
  .stats { order: 3; width: 100%; gap: 4px; margin-left: 0; }
  .stat { min-width: 0; flex: 1; padding: 5px 6px; gap: 5px; border-radius: 9px; }
  .stat-icon { display: none; }
  .stat-label { font-size: 6px; letter-spacing: 1px; }
  .stat-value { font-size: 10.5px; }
  .stat-sub { font-size: 7.5px; }
  .heat-bar { width: 44px; }
  .stat-rep { display: flex; }
  .top-actions { margin-left: auto; }
  .icon-btn { width: 30px; height: 30px; }
  .mission-strip { top: 88px; left: 8px; right: 8px; max-width: none; gap: 6px; padding: 6px 8px; }
  .mission-title { display: none; }
  .mission-obj { flex: 1; }
  .mission-prog { width: 38px; }
  .mission-go span { display: none; }
  .hint { bottom: 87px; font-size: 9px; padding: 6px 10px; max-width: calc(100vw - 20px); }
  .dock { bottom: max(7px, env(safe-area-inset-bottom)); width: calc(100% - 14px); padding: 4px; gap: 1px; border-radius: 15px; }
  .dock-btn { flex: 1; width: auto; height: 52px; border-radius: 10px; gap: 3px; }
  .dock-ico svg { width: 18px; height: 18px; }
  .dock-label { font-size: 6.5px; letter-spacing: .6px; }
  .dock-key { display: none; }
  .panel { top: auto; left: 7px; right: 7px; bottom: 70px; width: auto; max-height: 74vh; border-radius: 18px; transform: translateY(calc(100% + 30px)); }
  .panel.open { transform: translateY(0); }
  .panel-head { padding: 14px 15px 11px; }
  .panel-head h2 { font-size: 17px; }
  .panel-body { padding: 12px 13px 22px; }
  .toasts { top: auto; bottom: 82px; right: 8px; left: 8px; align-items: center; max-width: none; }
  .toast { width: 100%; font-size: 9.5px; }
  .modal-root { padding: 8px; align-items: flex-end; }
  .modal-inner { max-height: 94vh; }
  .story-card { grid-template-columns: 1fr; max-height: 92vh; border-radius: 18px; }
  .story-portrait { min-height: 0; height: 128px; border-right: 0; border-bottom: 1px solid var(--line); }
  .story-portrait canvas { height: 128px; object-position: center 22%; }
  .portrait-name { bottom: 9px; left: 13px; }
  .portrait-name b { font-size: 11px; }
  .portrait-name span { font-size: 6.5px; letter-spacing: 1.2px; }
  .story-main { padding: 14px 15px 13px; min-height: 0; overflow-y: auto; }
  .story-top { padding-right: 28px; }
  .story-title { font-size: 16px; margin-top: 6px; }
  .story-dialogue { padding: 10px 0 8px; min-height: 120px; }
  .story-text { font-size: 14px; line-height: 1.5; min-height: 66px; }
  .story-foot { padding-top: 9px; }
  .story-close { top: 8px; right: 8px; }
  .event-card, .raid-card, .ending-card, .refine-card, .offline-card { max-height: 90vh; overflow-y: auto; border-radius: 18px; }
  .raid-title { font-size: 30px; }
  .ending-title { font-size: 36px; }
  .ending-stats { grid-template-columns: repeat(2,1fr); }
  .splash-title { font-size: clamp(50px, 16vw, 76px); letter-spacing: -2px; }
  .splash-card { padding: 24px 18px; }
  .splash-blurb { font-size: 10px; }
  .splash-credit { display: none; }
  .brand-sub { display: none; }
  .scene-tip { display: none; }
}
@media (max-width: 380px) {
  .stat-rep { display: none; }
  .dock-label { font-size: 6px; }
  .mission-kicker { display: none; }
  .mission-strip { padding: 6px 8px; }
}
@media (min-width: 1600px) {
  .topbar { padding-left: 28px; padding-right: 28px; }
  .mission-strip { left: 28px; }
  .panel { width: 470px; right: 22px; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; }
}

// GREEN EMPIRE — interface, panels, story theatre, minigames.
import {
  STRAINS, STRAIN_BY_ID, PROPERTIES, PROPERTY_LIST, STAFF, STAFF_BY_ID,
  UPGRADES, UPGRADE_BY_ID, FRONTS, FRONT_BY_ID, BUFFS, PRICING, DAY_LENGTH,
  QUALITY_GRADES, gradeFor, rankFor
} from './data.js';
import { CHARACTERS } from './story.js';
import { MISSIONS } from './game.js';

const $ = id => document.getElementById(id);
const clamp = (n, a, b) => Math.max(a, Math.min(b, n));
const pad2 = n => String(n).padStart(2, '0');
const money = n => {
  n = Math.max(0, Math.round(n || 0));
  if (n >= 1000000) return '$' + (n / 1000000).toFixed(n >= 10000000 ? 1 : 2) + 'M';
  if (n >= 10000) return '$' + (n / 1000).toFixed(n >= 100000 ? 0 : 1) + 'K';
  return '$' + n.toLocaleString('en-US');
};
const num = n => Math.round(n || 0).toLocaleString('en-US');
const ico = (name, cls = '') => `<svg class="${cls}"><use href="#i-${name}"/></svg>`;

export class UI {
  constructor(game, renderer, audio) {
    this.game = game;
    this.renderer = renderer;
    this.audio = audio;
    this.activePanel = null;
    this.modalType = null;
    this.syncTimer = 0;
    this.panelRefresh = 0;
    this.typeTimer = null;
    this.refineTimer = null;
    this.refineSession = null;
    this.confirmReset = false;
    this.storyView = null;
    this.splashDone = false;
    this.lastHoverId = null;
    this.pendingRaid = null;
    this.bindBase();
    this.bindGame();
  }

  // ---------- boot & events ----------
  bindBase() {
    $('btnStart').addEventListener('click', () => this.startGame());
    $('dock').addEventListener('click', e => {
      const b = e.target.closest('.dock-btn');
      if (!b) return;
      this.audio?.click();
      if (b.dataset.action === 'story') this.openStory();
      else this.togglePanel(b.dataset.panel);
    });
    document.querySelectorAll('[data-panel]').forEach(el => {
      if (el.closest('.dock')) return;
      el.addEventListener('click', e => { e.preventDefault(); this.audio?.click(); this.openPanel(el.dataset.panel); });
    });
    $('panelClose').addEventListener('click', () => { this.audio?.click(); this.closePanel(); });
    $('panelBackdrop').addEventListener('click', () => this.closePanel());
    $('btnSound').addEventListener('click', () => this.toggleSound());
    $('modalRoot').addEventListener('click', e => {
      if (e.target === $('modalRoot') && this.modalType !== 'story') this.closeModal();
      const btn = e.target.closest('[data-act]');
      if (btn) this.modalAction(btn);
    });
    $('statCash').addEventListener('click', () => this.openPanel('laundry'));
    $('statStock').addEventListener('click', () => this.openPanel('grow'));
    $('statHeat').addEventListener('click', () => this.openPanel('heat'));
    $('statRep').addEventListener('click', () => this.openPanel('crew'));
    $('statDay').addEventListener('click', () => this.openPanel('settings'));
    $('missionStrip').addEventListener('click', () => this.openStory());
    this.bindCanvas();
    window.addEventListener('keydown', e => this.onKey(e));
    document.addEventListener('visibilitychange', () => { if (document.hidden) this.game.save(); });
  }

  bindGame() {
    const g = this.game;
    g.on('toast', d => this.toast(d.text, d.kind));
    g.on('raid', info => { this.closePanel(); this.openRaid(info); });
    g.on('betrayal', info => { this.closePanel(); this.openBetrayal(info); });
    g.on('event', ev => { this.closePanel(); this.openEvent(ev); });
    g.on('uiAction', d => {
      if (d.action === 'refine') this.openRefine();
      else if (d.action === 'panel') this.openPanel(d.panel);
    });
    g.on('propertyBought', () => { this.renderer.resize(); this.refreshPanel(); });
    g.on('property', () => { this.renderer.resize(); this.refreshPanel(); });
    g.on('ui', () => this.refreshPanel());
    window.addEventListener('resize', () => { this.renderer.resize(); });
  }

  startGame() {
    $('splash').classList.add('hidden');
    this.splashDone = true;
    this.game.setPaused(false);
    this.audio?.init();
    this.sync(0, true);
    const loaded = !!this.game.runtime.lastLoadSummary;
    setTimeout(() => {
      if (loaded && this.game.runtime.lastLoadSummary) { this.openOffline(this.game.runtime.lastLoadSummary); this.game.runtime.lastLoadSummary = null; }
      else if (!this.game.mission?.seen) this.openStory();
    }, 360);
  }

  bindCanvas() {
    const c = $('scene'), tip = $('sceneTip');
    c.addEventListener('pointerdown', e => {
      if (!this.splashDone || this.modalType || this.activePanel) return;
      const hit = this.renderer.pick(e.clientX, e.clientY);
      if (!hit) return;
      this.renderer.hoverId = hit.id;
      const before = hit.kind === 'slot' ? this.game.state.properties[hit.propId]?.slots[hit.index] : null;
      const res = this.game.interact(hit);
      if (hit.kind === 'customer') this.audio?.cash();
      else if (hit.kind === 'slot') {
        if (!before) this.audio?.plant();
        else if (before.progress >= 1) this.audio?.harvest();
        else this.audio?.water();
      }
      if (res && res.ok === false && res.msg) this.audio?.error();
      this.syncStats();
    });
    c.addEventListener('pointermove', e => {
      if (e.pointerType === 'touch') return;
      if (this.modalType || this.activePanel || !this.splashDone) { this.clearHover(); return; }
      const hit = this.renderer.pick(e.clientX, e.clientY);
      if (hit) {
        this.renderer.hoverId = hit.id;
        this.lastHoverId = hit.id;
        c.style.cursor = 'pointer';
        tip.textContent = this.renderer.labelFor(hit);
        tip.style.left = e.clientX + 'px';
        tip.style.top = e.clientY + 'px';
        tip.classList.add('show');
      } else this.clearHover();
    });
    c.addEventListener('pointerleave', () => this.clearHover());
  }

  clearHover() {
    this.renderer.hoverId = null;
    this.lastHoverId = null;
    $('scene').style.cursor = 'default';
    $('sceneTip').classList.remove('show');
  }

  onKey(e) {
    if (e.key === 'Escape') {
      if (this.modalType) this.closeModal();
      else if (this.activePanel) this.closePanel();
      return;
    }
    if (this.modalType === 'story' && (e.key === 'Enter' || e.key === ' ')) {
      if (this.storyView?.mode === 'dialogue') { e.preventDefault(); this.advanceStory(); }
      else if (this.storyView?.mode === 'reply') { e.preventDefault(); this.finishReply(); }
    }
    if (this.activePanel || this.modalType || !this.splashDone) return;
    const map = { '1': 'grow', '2': 'crew', '3': 'upgrades', '4': 'properties', '5': 'laundry', '6': 'story' };
    if (map[e.key]) {
      if (map[e.key] === 'story') this.openStory(); else this.togglePanel(map[e.key]);
    }
  }

  toggleSound() {
    const s = this.game.state.settings;
    s.sound = !s.sound;
    if (this.audio) this.audio.enabled = s.sound;
    $('soundIcon').setAttribute('href', s.sound ? '#i-sound-on' : '#i-sound-off');
    this.game.save();
    if (s.sound) this.audio?.init();
  }

  // ---------- periodic sync ----------
  sync(dt, force = false) {
    this.syncTimer += dt;
    if (!force && this.syncTimer > .22) {
      this.syncTimer = 0;
      this.syncStats();
      this.syncMission();
      this.syncHint();
      $('storyBadge').classList.toggle('show', !this.game.mission?.seen || this.game.missionProgress()?.complete);
      if (this.activePanel === 'laundry' || this.activePanel === 'heat') {
        this.panelRefresh += .22;
        if (this.panelRefresh > 1.1) { this.panelRefresh = 0; this.refreshPanel(true); }
      }
    }
    if (force) { this.syncStats(); this.syncMission(); this.syncHint(); }
    $('soundIcon').setAttribute('href', this.game.state.settings.sound ? '#i-sound-on' : '#i-sound-off');
  }

  syncStats() {
    const s = this.game.state;
    $('cashDirty').textContent = money(s.dirty);
    $('cashClean').textContent = 'clean ' + money(s.clean);
    const grams = this.game.stockGrams();
    const q = this.game.qualityAvg();
    $('stockValue').textContent = `${Math.floor(grams)}g`;
    $('stockQuality').textContent = grams ? `Q${Math.round(q)} · ${gradeFor(q).name}` : 'empty';
    $('repValue').textContent = Math.round(s.rep);
    $('repRank').textContent = rankFor(s.rep);
    $('heatValue').textContent = Math.round(s.heat) + '%';
    $('heatBar').style.width = clamp(s.heat, 0, 100) + '%';
    $('heatValue').style.color = s.heat > 70 ? '#ff8f86' : s.heat > 45 ? '#ffd27a' : '#ffb4a8';
    $('dayValue').textContent = 'D' + s.day;
    const h = this.game.hour;
    $('clockValue').textContent = `${pad2(Math.floor(h))}:${pad2(Math.floor((h % 1) * 60))}`;
    $('statHeat').title = `Police heat: ${this.game.heatLabel()}`;
  }

  syncMission() {
    const m = this.game.mission;
    const strip = $('missionStrip');
    if (!m) {
      $('missionKicker').textContent = 'ENDGAME';
      $('missionTitle').textContent = 'The city is yours';
      $('missionObj').textContent = 'Keep building. Buy fronts, expand, survive.';
      $('missionBar').style.width = '100%';
      $('storyBadge').classList.remove('show');
      strip.classList.remove('ready');
      return;
    }
    const p = this.game.missionProgress();
    $('missionKicker').textContent = `MISSION ${pad2(this.game.state.story.idx + 1)}`;
    $('missionTitle').textContent = m.title;
    $('missionObj').textContent = `${m.objective.label} · ${Math.floor(p.current)}/${p.target}`;
    $('missionBar').style.width = (p.pct * 100) + '%';
    strip.classList.toggle('ready', p.complete);
  }

  syncHint() {
    const hint = $('hintBar'), txt = $('hintText');
    const g = this.game, s = g.state;
    if (!s.settings.hints || this.modalType || this.activePanel || !this.splashDone) { hint.classList.add('hidden'); return; }
    const slots = g.propState.slots;
    const ready = slots.some(x => x && x.progress >= 1);
    const empty = slots.filter(x => !x).length;
    const wait = g.runtime.customers.some(c => c.state === 'wait');
    let text = '';
    if (this.renderer.shake > 0) text = 'The police are inside. Let them leave.';
    else if (ready) text = 'A plant is ready — tap it to harvest.';
    else if (wait) text = 'Tap a customer to serve them.';
    else if (empty && g.state.dirty >= STRAIN_BY_ID[g.selectedStrainId()].cost) text = 'Tap an empty pot to plant another seed.';
    else if (s.heat > 72) text = 'Heat is critical. Open HEAT to bribe or lay low.';
    else if (g.stockGrams() > 0) text = 'Product ready. Customers are on the way — tap them before they leave.';
    else if (!g.mission?.seen && g.mission) text = 'New story mission available. Open STORY.';
    else text = 'Tend plants for bonus quality. Upgrade gear to grow faster.';
    txt.textContent = text;
    hint.classList.remove('hidden');
  }

  // ---------- toasts ----------
  toast(text, kind = 'info') {
    if (!text) return;
    const root = $('toasts');
    const el = document.createElement('div');
    el.className = `toast ${kind}`;
    el.textContent = text;
    root.appendChild(el);
    while (root.children.length > 4) root.firstElementChild.remove();
    setTimeout(() => { el.classList.add('out'); setTimeout(() => el.remove(), 320); }, 3800);
  }

  // ---------- panels ----------
  togglePanel(name) { this.openPanel(this.activePanel === name ? null : name); }

  openPanel(name) {
    if (!name) return this.closePanel();
    if (this.modalType) return;
    this.activePanel = name;
    this.game.setPaused(true);
    const meta = {
      grow: ['OPERATIONS', 'Grow Room'], crew: ['THE CREW', 'People & Payroll'],
      upgrades: ['EQUIPMENT', 'Upgrade Bench'], properties: ['REAL ESTATE', 'The Empire'],
      laundry: ['MONEY', 'Laundry & Fronts'], heat: ['RISK', 'Heat & Police'], settings: ['SYSTEM', 'Settings']
    };
    $('panelKicker').textContent = meta[name]?.[0] || 'MENU';
    $('panelTitle').textContent = meta[name]?.[1] || name;
    $('panelSub').textContent = this.panelSub(name);
    $('panelBody').innerHTML = this.panelHTML(name);
    $('panel').classList.add('open');
    $('panelBackdrop').classList.add('open');
    this.bindPanelBody();
    document.querySelectorAll('.dock-btn').forEach(b => b.classList.toggle('active', b.dataset.panel === name));
    this.syncHint();
  }

  closePanel() {
    this.activePanel = null;
    $('panel').classList.remove('open');
    $('panelBackdrop').classList.remove('open');
    document.querySelectorAll('.dock-btn').forEach(b => b.classList.remove('active'));
    if (!this.modalType) this.game.setPaused(false);
    this.syncHint();
    this.renderer.resize();
  }

  refreshPanel(preserve = false) {
    if (!this.activePanel) return;
    const body = $('panelBody');
    const scroll = body.scrollTop;
    if (!preserve) $('panelSub').textContent = this.panelSub(this.activePanel);
    body.innerHTML = this.panelHTML(this.activePanel);
    this.bindPanelBody();
    if (preserve) body.scrollTop = scroll;
  }

  panelSub(name) {
    const g = this.game, s = g.state;
    if (name === 'grow') return `${g.propConfig.name} · ${g.propState.slots.filter(Boolean).length}/${g.propState.slots.length} pots growing`;
    if (name === 'crew') return `${s.staff.length} on payroll · ${money(g.wageTotal)}/day`;
    if (name === 'upgrades') return `${g.propConfig.name} · equipment levels`;
    if (name === 'properties') return `${PROPERTY_LIST.filter(p => s.properties[p.id].owned).length}/${PROPERTY_LIST.length} properties owned`;
    if (name === 'laundry') return `${s.fronts.length} fronts · clean cash buys legitimacy`;
    if (name === 'heat') return `${g.heatLabel()} · ${Math.round(s.heat)}% police interest`;
    if (name === 'settings') return 'Save, sound, hints and the nuclear option';
    return '';
  }

  bindPanelBody() {
    $('panelBody').addEventListener('click', e => {
      const el = e.target.closest('[data-act]');
      if (!el) return;
      this.panelAction(el.dataset.act, el.dataset, el);
    }, { once: true });
  }

  panelAction(act, data, el) {
    const g = this.game;
    this.audio?.click();
    if (act === 'select') { g.selectStrain(data.id); this.refreshPanel(); }
    else if (act === 'pricing') { g.state.pricing = data.id; g.save(); this.refreshPanel(); }
    else if (act === 'replant') { g.replantAll(); this.refreshPanel(); }
    else if (act === 'buff') {
      const r = g.buyBuff(data.id);
      if (!r.ok) { this.toast(r.msg || 'Cannot buy that.', 'warn'); this.audio?.error(); }
      else { this.toast(`${r.b.name} active for 3 harvests.`, 'good'); this.refreshPanel(); }
    }
    else if (act === 'refine') { this.closePanel(); this.openRefine(data.id); }
    else if (act === 'hire') {
      const r = g.hireStaff(data.id);
      if (!r.ok) { this.toast(r.msg || 'Cannot hire.', 'warn'); this.audio?.error(); }
      else { this.toast(`${r.staff.name} joined the crew.`, 'good'); this.audio?.success(); this.renderer.sparkleScreen(); this.refreshPanel(); }
    }
    else if (act === 'upgrade') {
      const r = g.buyUpgrade(g.state.activeProperty, data.id);
      if (!r.ok) { this.toast(r.msg || 'Cannot upgrade.', 'warn'); this.audio?.error(); }
      else { this.toast(`${UPGRADE_BY_ID[data.id].name} upgraded.`, 'good'); this.audio?.success(); this.refreshPanel(); }
    }
    else if (act === 'buyprop') {
      const r = g.buyProperty(data.id);
      if (!r.ok) { this.toast(r.msg || 'Cannot buy.', 'warn'); this.audio?.error(); }
      else { this.toast(r.moved ? `Moved to ${PROPERTIES[data.id].name}.` : `Bought ${PROPERTIES[data.id].name}.`, 'good'); this.audio?.success(); this.renderer.sparkleScreen(); this.renderer.resize(); this.refreshPanel(); }
    }
    else if (act === 'visit') { g.moveProperty(data.id); this.toast(`Moved to ${PROPERTIES[data.id].name}.`, 'info'); this.renderer.resize(); this.refreshPanel(); }
    else if (act === 'launder') {
      const r = g.launder(data.amount === 'all' ? 'all' : Number(data.amount));
      if (!r.ok) { this.toast(r.msg || 'Cannot launder.', 'warn'); this.audio?.error(); }
      else { this.toast(`Washed ${money(r.amount)} → ${money(r.cleanGain)} clean.`, 'good'); this.audio?.cash(); this.refreshPanel(); }
    }
    else if (act === 'front') {
      const r = g.buyFront(data.id);
      if (!r.ok) { this.toast(r.msg || 'Cannot buy front.', 'warn'); this.audio?.error(); }
      else { this.toast(`${r.f.name} acquired. The money has a porch now.`, 'good'); this.audio?.success(); this.renderer.sparkleScreen(); this.refreshPanel(); }
    }
    else if (act === 'bribe') {
      const r = g.bribe();
      if (!r.ok) { this.toast(r.msg || 'No one is buying.', 'warn'); this.audio?.error(); }
      else { this.toast(`Bribed the precinct. Heat -26%.`, 'good'); this.audio?.cash(); this.refreshPanel(); }
    }
    else if (act === 'laylow') {
      g.layLow(50);
      this.toast('Lights out for 50 seconds. No customers, less heat.', 'info');
      this.refreshPanel();
    }
    else if (act === 'settingsSound') { this.toggleSound(); this.refreshPanel(); }
    else if (act === 'settingsHints') { g.state.settings.hints = !g.state.settings.hints; g.save(); this.refreshPanel(); }
    else if (act === 'save') { g.save(); this.toast('Empire saved locally.', 'good'); this.audio?.success(); }
    else if (act === 'reset1') { this.confirmReset = true; this.refreshPanel(); }
    else if (act === 'reset2') {
      g.save();
      localStorage.removeItem('greenEmpire.save.v2');
      g.freshStart();
      this.closePanel();
      location.reload();
    }
  }

  // ---------- panel templates ----------
  panelHTML(name) {
    if (name === 'grow') return this.growHTML();
    if (name === 'crew') return this.crewHTML();
    if (name === 'upgrades') return this.upgradesHTML();
    if (name === 'properties') return this.propertiesHTML();
    if (name === 'laundry') return this.laundryHTML();
    if (name === 'heat') return this.heatHTML();
    if (name === 'settings') return this.settingsHTML();
    return '';
  }

  growHTML() {
    const g = this.game, s = g.state, p = g.propState;
    const strain = STRAIN_BY_ID[g.selectedStrainId()];
    const lots = Object.entries(s.inventory).filter(([, l]) => l?.g > 0)
      .sort((a, b) => (STRAIN_BY_ID[b[0]]?.price || 0) - (STRAIN_BY_ID[a[0]]?.price || 0));
    const invHTML = lots.length ? lots.map(([id, lot]) => {
      const st = STRAIN_BY_ID[id];
      const grade = gradeFor(lot.q);
      return `<div class="inv-row">
        <span class="dot" style="background:${st.color}"></span>
        <div class="grow"><div class="between"><b class="small">${st.name}</b><span class="small gold">${lot.g.toFixed(0)}g</span></div>
        <div class="between" style="margin-top:2px"><span class="tiny" style="color:${grade.color}">Q${Math.round(lot.q)} ${grade.name}</span><span class="tiny muted">${money(lot.g * g.sellPrice(id, lot.q, 1))}</span></div></div>
        ${g.canRefine() && lot.g >= 10 ? `<button class="btn small ghost" data-act="refine" data-id="${id}">REFINE</button>` : ''}
      </div>`;
    }).join('') : `<div class="empty">${ico('leaf')}No product in stock.<br>Plant a seed and harvest.</div>`;

    const strains = STRAINS.map(st => {
      const locked = !g.strainUnlocked(st.id);
      const active = g.selectedStrainId() === st.id;
      return `<div class="strain-card ${active ? 'active' : ''} ${locked ? 'locked' : ''}" ${locked ? '' : `data-act="select" data-id="${st.id}"`}>
        <span class="strain-swatch" style="background:${st.color}"></span>
        <div class="strain-main">
          <div class="strain-name">${st.name} ${active ? `<span class="chip green">SELECTED</span>` : ''}</div>
          <div class="strain-desc">${st.desc}</div>
          <div class="strain-stats"><span class="chip">${st.growTime}s</span><span class="chip">~${st.yield}g</span><span class="chip">base Q${st.quality}</span><span class="chip gold">$${st.price}/g</span></div>
        </div>
        <div class="strain-side">${locked ? `<span class="chip"><svg style="width:10px;height:10px"><use href="#i-lock"/></svg> STORY</span><span class="strain-lock">UNLOCKS LATER</span>` : `<span class="strain-cost">$${st.cost}</span><span class="strain-lock">SEED</span>`}</div>
      </div>`;
    }).join('');

    const buff = s.buff ? (() => {
      const b = BUFFS.find(x => x.id === s.buff.id);
      return `<div class="card" style="border-color:${b.color}55"><div class="between"><div><div class="small" style="font-weight:800;color:${b.color}">${b.name} ACTIVE</div><div class="tiny muted">${b.desc}</div></div><span class="chip" style="color:${b.color}">${s.buff.charges} HARVESTS</span></div></div>`;
    })() : BUFFS.map(b => `<div class="card" style="padding:9px 10px"><div class="between"><div><div class="small" style="font-weight:800">${b.name}</div><div class="tiny muted">${b.desc}</div></div><button class="btn small ghost" data-act="buff" data-id="${b.id}">$${b.cost}</button></div></div>`).join('');

    return `
      <div class="sec-title">INVENTORY <em>${Math.floor(g.stockGrams())}g · ${money(g.stockGrams() * (lots.length ? g.sellPrice(lots[0][0], lots[0][1].q, 1) : 0))}</em></div>
      <div class="card">${invHTML}</div>

      <div class="sec-title">STRAIN LIBRARY <em>tap to select</em></div>
      ${strains}

      <div class="sec-title">SEED & PLANT <em>${s.freePlantings ? s.freePlantings + ' free plantings' : ''}</em></div>
      <div class="card">
        <div class="between"><div><div class="small" style="font-weight:800">Selected: ${strain.name}</div><div class="tiny muted">${p.slots.filter(x => !x).length} empty pots · seed $${strain.cost}</div></div>
        <button class="btn small" data-act="replant">REPLANT ALL</button></div>
      </div>

      <div class="sec-title">NUTRIENTS <em>one at a time</em></div>
      ${buff}

      <div class="sec-title">PRICING STRATEGY <em>applies city-wide</em></div>
      <div class="price-grid">
        ${Object.entries(PRICING).map(([id, pr]) => `<button class="price-opt ${s.pricing === id ? 'active' : ''}" data-act="pricing" data-id="${id}"><b>${pr.name}</b>${(pr.mod * 100 - 100 >= 0 ? '+' : '')}${Math.round((pr.mod - 1) * 100)}% cash<span>${pr.rep >= 1 ? '+rep' : '-rep'}</span></button>`).join('')}
      </div>
      <p class="tiny muted" style="margin-top:8px;line-height:1.5">${PRICING[s.pricing].note} Higher prices raise heat faster.</p>
      ${g.canRefine() ? `<button class="btn ghost wide" style="margin-top:12px" data-act="refine">${ico('flask')} OPEN CHEM STATION</button>` : ''}
    `;
  }

  crewHTML() {
    const g = this.game, s = g.state;
    const locked = !g.staffUnlocked();
    const nextPay = Math.max(0, DAY_LENGTH - s.dayTime);
    const staff = STAFF.map(st => {
      const hired = s.staff.includes(st.id);
      return `<div class="card"><div class="staff-card">
        <div class="avatar" style="background:${st.color}">${st.name[0]}</div>
        <div class="staff-info">
          <div class="staff-name">${st.name} <span class="role">${st.role}</span></div>
          <div class="staff-desc">${st.desc}</div>
          <div class="row" style="margin-top:5px"><span class="chip" style="color:${st.color}">${st.power}</span><span class="wage">$${st.wage}/day</span></div>
        </div>
        ${hired ? '<span class="chip green">HIRED</span>' : `<button class="btn small" data-act="hire" data-id="${st.id}" ${locked ? 'disabled' : ''}>$${st.cost}</button>`}
      </div></div>`;
    }).join('');
    return `
      ${locked ? `<div class="card" style="border-color:rgba(255,207,107,.3)"><div class="small" style="font-weight:800">🔒 Crew unlocks after the garage</div><div class="tiny muted">Advance the story to hire people. They automate the boring parts.</div></div>` : ''}
      <div class="card"><div class="between">
        <div><div class="mini-label">DAILY PAYROLL</div><div style="font-size:18px;font-weight:900">${money(g.wageTotal)}</div></div>
        <div style="text-align:right"><div class="mini-label">NEXT PAYDAY</div><div class="small gold">${Math.floor(nextPay / 60)}m ${pad2(Math.floor(nextPay % 60))}s</div></div>
      </div></div>
      <div class="sec-title">AVAILABLE CREW <em>${s.staff.length} hired</em></div>
      ${staff}
      <div class="card"><div class="tiny muted">Wages are taken from dirty cash at daybreak. If you can't pay, they walk. Auto-harvest and auto-sell keep working while you're here — and plants keep growing while you're away.</div></div>
    `;
  }

  upgradesHTML() {
    const g = this.game, p = g.propConfig, ps = g.propState;
    const list = UPGRADES.map(u => {
      const lvl = ps.upgrades[u.id] || 0;
      const maxed = lvl >= u.max;
      const cost = g.upgradeCost(u.id, lvl);
      return `<div class="card"><div class="upg-card">
        <div class="upg-icon">${ico(u.icon)}</div>
        <div class="grow"><div class="between"><div class="small" style="font-weight:800">${u.name}</div><span class="tiny muted">Lv ${lvl}/${u.max}</span></div>
        <div class="tiny muted">${u.desc}</div>
        <div class="pips">${Array.from({ length: u.max }, (_, i) => `<i class="${i < lvl ? 'on' : ''}"></i>`).join('')}</div></div>
        ${maxed ? '<span class="chip green">MAX</span>' : `<button class="btn small" data-act="upgrade" data-id="${u.id}">$${num(cost)}</button>`}
      </div></div>`;
    }).join('');
    const light = ps.upgrades.lights * 12 + Math.round(p.growthMod * 100);
    const qmod = ps.upgrades.vent * 4 + ps.upgrades.irrigation * 2 + p.qualityMod;
    const price = Math.round((p.priceMod * (1 + ps.upgrades.counter * .07) * 100 - 100));
    return `
      <div class="card"><div class="between"><div><div class="mini-label">FACILITY</div><div class="small" style="font-weight:800">${p.name}</div></div><span class="chip green">OWNED</span></div>
        <div class="row" style="gap:5px;flex-wrap:wrap;margin-top:8px"><span class="chip">+${light}% growth</span><span class="chip">+${qmod} quality</span><span class="chip">+${price}% prices</span></div>
      </div>
      <div class="sec-title">EQUIPMENT <em>upgrades apply to this property</em></div>
      ${list}
      <p class="tiny muted" style="line-height:1.5;margin-top:6px">Each property has its own equipment. Better properties start with stronger bonuses and more pots.</p>
    `;
  }

  propertiesHTML() {
    const g = this.game, s = g.state;
    const cards = PROPERTY_LIST.map((p, i) => {
      const ps = s.properties[p.id];
      const owned = ps.owned;
      const active = s.activeProperty === p.id;
      const available = g.propertyAvailable(p.id);
      const canBuy = !owned && available && s.clean >= p.cost;
      const pal = p.palette;
      return `<div class="card prop-card" style="${active ? 'border-color:rgba(200,255,110,.45)' : ''}">
        <div class="prop-visual" style="background:linear-gradient(135deg, ${pal.wallR} 0%, ${pal.floorA} 55%, #0a100d 100%)">
          <div class="tags">${active ? '<span class="chip green">YOU ARE HERE</span>' : owned ? '<span class="chip">OWNED</span>' : available ? `<span class="chip gold">$${num(p.cost)} CLEAN</span>` : `<span class="chip red"><svg style="width:9px;height:9px"><use href="#i-lock"/></svg> STORY LOCKED</span>`}</div>
        </div>
        <div class="prop-body">
          <div class="between"><div><div class="prop-title">${p.name}</div><div class="tiny muted">${p.act} · ${p.short}</div></div><span class="chip">${p.slots.length} POTS</span></div>
          <div class="prop-sub">${p.tagline}</div>
          <div class="prop-stats"><span class="chip">+${Math.round(p.priceMod * 100 - 100)}% prices</span><span class="chip">+${Math.round(p.growthMod * 100)}% growth</span><span class="chip">+${p.qualityMod} quality</span><span class="chip">+${Math.round(p.yieldMod * 100)}% yield</span></div>
          <div class="prop-foot">
            <span class="tiny muted">${owned ? 'Equipment ready' : available ? 'Requires clean cash' : 'Advance the story'}</span>
            ${owned ? (active ? '<span class="chip green">CURRENT</span>' : `<button class="btn small ghost" data-act="visit" data-id="${p.id}">VISIT</button>`) : `<button class="btn small" data-act="buyprop" data-id="${p.id}" ${canBuy ? '' : 'disabled'}>${available ? `BUY $${num(p.cost)}` : `MISSION ${p.reqMission + 1}`}</button>`}
          </div>
        </div>
      </div>`;
    }).join('');
    return `<div class="card"><div class="between"><div><div class="mini-label">EMPIRE VALUE</div><div style="font-size:19px;font-weight:900">${money(g.netWorth())}</div></div><div style="text-align:right"><div class="mini-label">CLEAN CASH</div><div class="green" style="font-size:15px;font-weight:800">${money(s.clean)}</div></div></div>
      <div class="tiny muted" style="margin-top:6px">Properties must be bought with clean cash. Dirty cash needs laundering first.</div></div>
      <div class="sec-title">PROPERTIES <em>${PROPERTY_LIST.filter(p => s.properties[p.id].owned).length}/${PROPERTY_LIST.length} owned</em></div>
      ${cards}`;
  }

  laundryHTML() {
    const g = this.game, s = g.state;
    const rate = Math.round((.72 + (s.fronts.includes('legal') ? .06 : 0)) * 100);
    const auto = s.fronts.reduce((n, id) => n + (FRONT_BY_ID[id]?.rate || 0), 0);
    const fronts = FRONTS.map(f => {
      const owned = s.fronts.includes(f.id);
      const locked = s.story.idx < f.req;
      return `<div class="card"><div class="front-card">
        <div class="front-icon">${f.id === 'legal' ? '⚖️' : f.id === 'carwash' ? '🚗' : f.id === 'chicken' ? '🍗' : '🍸'}</div>
        <div class="grow"><div class="between"><div class="small" style="font-weight:800">${f.name}</div>${owned ? '<span class="chip green">OWNED</span>' : ''}</div>
        <div class="tiny muted">${f.kind} · ${f.desc}</div>
        <div class="row" style="margin-top:5px;flex-wrap:wrap"><span class="chip gold">${f.tag}</span>${f.rep ? `<span class="chip green">+${f.rep} rep</span>` : ''}</div></div>
        ${!owned ? `<button class="btn small" data-act="front" data-id="${f.id}" ${locked || s.clean < f.cost ? 'disabled' : ''}>$${num(f.cost)}</button>` : ''}
      </div></div>`;
    }).join('');
    return `
      <div class="laundry-hero">
        <div style="flex:1"><div class="mini-label">DIRTY CASH</div><div class="laundry-money dirty">${money(s.dirty)}</div></div>
        <div class="swap-arrow" style="font-size:18px">→</div>
        <div style="flex:1;text-align:right"><div class="mini-label">CLEAN CASH</div><div class="laundry-money clean">${money(s.clean)}</div></div>
      </div>
      <div class="card">
        <div class="between"><div><div class="small" style="font-weight:800">Manual wash · ${rate}% return</div><div class="tiny muted">Laundering cools police interest.</div></div><span class="chip">${s.fronts.includes('legal') ? 'LAWYER +6%' : 'NO LAWYER'}</span></div>
        <div class="btn-row" style="margin-top:9px">
          <button class="btn small ghost" data-act="launder" data-amount="500" ${s.dirty < 500 ? 'disabled' : ''}>WASH $500</button>
          <button class="btn small ghost" data-act="launder" data-amount="2500" ${s.dirty < 2500 ? 'disabled' : ''}>WASH $2.5K</button>
          <button class="btn small" data-act="launder" data-amount="all" ${s.dirty < 10 ? 'disabled' : ''}>WASH ALL</button>
        </div>
      </div>
      <div class="card"><div class="between"><div><div class="mini-label">AUTOMATIC LAUNDERING</div><div class="small" style="font-weight:800">${auto ? `$${num(auto)} dirty / minute` : 'No fronts owned'}</div></div><div style="text-align:right"><div class="mini-label">FRONTS</div><div class="small">${s.fronts.length}</div></div></div>
      <div class="tiny muted" style="margin-top:5px">Fronts wash money passively while you play and while you're away. They also make the city respect you.</div></div>
      <div class="sec-title">LEGITIMATE FRONTS <em>clean cash only</em></div>
      ${fronts}
      <div class="card"><div class="tiny muted">Clean cash buys properties and fronts. Dirty cash buys seeds, upgrades and wages. Keep both moving, or the empire stalls.</div></div>
    `;
  }

  heatHTML() {
    const g = this.game, s = g.state;
    const bribe = g.bribeCost();
    const sec = g.propState.upgrades.security;
    const cooling = (0.1 + (s.fronts.includes('legal') ? .2 : 0) + sec * .02).toFixed(2);
    const stateCol = s.heat > 75 ? 'red' : s.heat > 45 ? 'gold' : 'green';
    return `
      <div class="card">
        <div class="between"><div><div class="mini-label">POLICE INTEREST</div><div style="font-size:26px;font-weight:900" class="${stateCol}">${Math.round(s.heat)}%</div></div><span class="chip ${stateCol}">${g.heatLabel()}</span></div>
        <div class="heat-gauge"><i style="width:${clamp(s.heat, 0, 100)}%"></i></div>
        <div class="heat-scale"><span>INVISIBLE</span><span>WATCHED</span><span>RAID</span></div>
        <div class="tiny muted" style="margin-top:8px;line-height:1.5">Sales raise heat. Property raids start at 100%. At 100%, police seize cash and stock and one plant is destroyed.</div>
      </div>
      <div class="card">
        <div class="between"><div><div class="small" style="font-weight:800">Bribe the precinct</div><div class="tiny muted">Heat -26% instantly. Cost scales with heat.</div></div><button class="btn small" data-act="bribe" ${s.heat < 6 || s.dirty < bribe ? 'disabled' : ''}>$${num(bribe)}</button></div>
      </div>
      <div class="card">
        <div class="between"><div><div class="small" style="font-weight:800">Lay low</div><div class="tiny muted">No customers for 50s. Heat -9%. Lets the room cool.</div></div><button class="btn small ghost" data-act="laylow">LAY LOW</button></div>
      </div>
      <div class="sec-title">YOUR DEFENCES</div>
      <div class="card"><div class="row" style="gap:6px;flex-wrap:wrap"><span class="chip">Cooling ${cooling}%/s</span><span class="chip">Security Lv ${sec}</span><span class="chip ${s.staff.includes('bruno') ? 'green' : ''}">${s.staff.includes('bruno') ? 'BRUNO ON DUTY' : 'NO MUSCLE'}</span><span class="chip gold">${s.stats.raids} raids survived</span></div>
        <div class="tiny muted" style="margin-top:7px">Upgrade Security in the Upgrades panel and hire Bruno to reduce heat gain and raid losses.</div></div>
      <div class="card"><div class="tiny muted">Tip: Laundering $500+ lowers heat. A lawyer on retainer cools the city passively.</div></div>
    `;
  }

  settingsHTML() {
    const g = this.game, s = g.state;
    const played = Math.floor(s.stats.played / 60);
    return `
      <div class="card"><div class="between"><div><div class="small" style="font-weight:800">Manual save</div><div class="tiny muted">Autosaves every 12 seconds.</div></div><button class="btn small" data-act="save">SAVE NOW</button></div></div>
      <div class="card"><div class="between"><div><div class="small" style="font-weight:800">Sound</div><div class="tiny muted">Synth clicks, cash and sirens.</div></div><button class="toggle ${s.settings.sound ? 'on' : ''}" data-act="settingsSound" aria-label="Toggle sound"></button></div></div>
      <div class="card"><div class="between"><div><div class="small" style="font-weight:800">Hints</div><div class="tiny muted">Contextual tips above the dock.</div></div><button class="toggle ${s.settings.hints ? 'on' : ''}" data-act="settingsHints" aria-label="Toggle hints"></button></div></div>
      <div class="sec-title">EMPIRE RECORD</div>
      <div class="card">
        <div class="between"><span class="tiny muted">Net worth</span><span class="small green">${money(g.netWorth())}</span></div>
        <div class="between" style="margin-top:5px"><span class="tiny muted">Time played</span><span class="small">${played}m</span></div>
        <div class="between" style="margin-top:5px"><span class="tiny muted">Plants harvested</span><span class="small">${s.stats.harvests}</span></div>
        <div class="between" style="margin-top:5px"><span class="tiny muted">Grams sold</span><span class="small">${Math.floor(s.stats.sold)}g</span></div>
        <div class="between" style="margin-top:5px"><span class="tiny muted">Lifetime earnings</span><span class="small gold">${money(s.stats.earned)}</span></div>
        <div class="between" style="margin-top:5px"><span class="tiny muted">Raids survived</span><span class="small red">${s.stats.raids}</span></div>
      </div>
      <div class="sec-title">DANGER ZONE</div>
      <div class="card" style="border-color:rgba(255,112,112,.22)">
        <div class="between"><div><div class="small" style="font-weight:800">Start over</div><div class="tiny muted">Deletes your save, cash, properties and story progress.</div></div>
          ${this.confirmReset ? '<button class="btn small danger" data-act="reset2">CONFIRM WIPE</button>' : '<button class="btn small ghost" data-act="reset1">RESET</button>'}
        </div>
        ${this.confirmReset ? '<div class="tiny red" style="margin-top:6px">This cannot be undone. Click CONFIRM WIPE to erase everything.</div>' : ''}
      </div>
      <p class="tiny muted" style="line-height:1.5;margin-top:10px">GREEN EMPIRE v1.0 · An original fictional crime saga. 18+ themes. Built as a single-page game; save data lives in your browser.</p>
    `;
  }

  //__MORE__
}

input.newString:
// ---------- story theatre ----------
setModal(html, type) {
  $('modalRoot').innerHTML = `<div class="modal-inner">${html}</div>`;
  $('modalRoot').classList.add('open');
  this.modalType = type;
  this.game.setPaused(true);
  this.syncHint();
}

closeModal() {
  if (this.typeTimer) { clearInterval(this.typeTimer); this.typeTimer = null; }
  if (this.refineTimer) { clearInterval(this.refineTimer); this.refineTimer = null; }
  this.refineSession = null;
  $('modalRoot').classList.remove('open');
  this.modalType = null;
  this.storyView = null;
  if (!this.activePanel) this.game.setPaused(false);
  this.syncHint();
}

modalAction(btn) {
  const act = btn.dataset.act;
  if (act === 'storyClose') { this.closeModal(); return; }
  if (act === 'storyAdvance') { this.advanceStory(); return; }
  if (act === 'storyChoice') { this.chooseStory(Number(btn.dataset.index)); return; }
  if (act === 'storyClaim') { this.claimMission(); return; }
  if (act === 'storyReplay') { this.startStoryDialogue(this.game.mission, true); return; }
  if (act === 'eventChoice') { this.chooseEvent(Number(btn.dataset.index)); return; }
  if (act === 'eventClose') { this.closeModal(); return; }
  if (act === 'raidClose' || act === 'endingClose' || act === 'offlineClose') { this.closeModal(); return; }
  if (act === 'endingReset') { this.closeModal(); this.openPanel('settings'); return; }
  if (act === 'refinePick') { this.startRefine(btn.dataset.id); return; }
  if (act === 'refineGo') { this.resolveRefine(false); return; }
  if (act === 'refineAuto') { this.resolveRefine(true); return; }
  if (act === 'refineDone') { this.closeModal(); if (this.activePanel) this.refreshPanel(); return; }
  if (act === 'refineCancel') { this.closeModal(); return; }
}

openStory() {
  const g = this.game;
  if (this.modalType) return;
  if (this.activePanel) this.closePanel();
  const m = g.mission;
  if (!m) { this.openStoryComplete(); return; }
  this.audio?.click();
  if (!g.state.story.seen) this.startStoryDialogue(m);
  else this.showStorySummary(m);
}

storyShell(m) {
  const ch = CHARACTERS[m.lines[0]?.s] || CHARACTERS.narrator;
  return `<div class="story-card">
    <button class="icon-btn story-close" data-act="storyClose" aria-label="Close story">${ico('close')}</button>
    <div class="story-portrait">
      <canvas id="storyPortrait" width="320" height="440"></canvas>
      <div class="portrait-vignette"></div>
      <div class="portrait-name"><b id="storyName">${ch.name}</b><span id="storyRole">${ch.role || ''}</span></div>
    </div>
    <div class="story-main">
      <div class="story-top"><div><div class="story-act">${m.act} · MISSION ${pad2(this.game.state.story.idx + 1)}</div><div class="story-place">${m.place}</div></div></div>
      <div class="story-title">${m.title}</div>
      <div class="story-dialogue" id="storyDialogue" data-act="storyAdvance">
        <div class="story-speaker" id="storySpeaker"></div>
        <div class="story-text" id="storyText"></div>
        <div id="storyChoices"></div>
      </div>
      <div class="story-foot">
        <div class="story-dots" id="storyDots"></div>
        <div class="story-next" id="storyNext">TAP TO CONTINUE ${ico('arrow')}</div>
      </div>
    </div>
  </div>`;
}

startStoryDialogue(m, replay = false) {
  this.storyView = { mode: 'dialogue', mission: m, line: 0, typing: false, typed: 0, text: '', speakerId: '', replay };
  this.setModal(this.storyShell(m), 'story');
  this.renderStoryLine();
}

renderStoryLine() {
  const v = this.storyView;
  if (!v) return;
  const line = v.mission.lines[v.line];
  if (!line) { this.afterDialogue(); return; }
  const ch = CHARACTERS[line.s] || CHARACTERS.narrator;
  v.speakerId = line.s;
  $('storyName').textContent = ch.name;
  $('storyRole').textContent = ch.role || '';
  $('storySpeaker').textContent = ch.narrator ? 'THE CITY' : ch.name;
  $('storySpeaker').style.opacity = ch.narrator ? '.65' : '1';
  $('storyText').className = 'story-text' + (ch.narrator ? ' narrator typing' : ' typing');
  $('storyChoices').innerHTML = '';
  $('storyNext').style.visibility = 'visible';
  $('storyNext').innerHTML = `TAP TO CONTINUE ${ico('arrow')}`;
  $('storyDots').innerHTML = v.mission.lines.map((_, i) => `<i class="${i === v.line ? 'on' : ''}"></i>`).join('');
  if (line.s !== v.lastSpeaker) { this.drawPortrait($('storyPortrait'), line.s); v.lastSpeaker = line.s; }
  v.text = line.t; v.typed = 0; v.typing = true;
  $('storyText').textContent = '';
  clearInterval(this.typeTimer);
  this.typeTimer = setInterval(() => {
    if (!this.storyView || this.storyView.mode !== 'dialogue') { clearInterval(this.typeTimer); return; }
    v.typed += 2;
    if (v.typed >= v.text.length) {
      v.typed = v.text.length; v.typing = false;
      $('storyText').textContent = v.text;
      $('storyText').classList.remove('typing');
      clearInterval(this.typeTimer);
    } else {
      $('storyText').textContent = v.text.slice(0, v.typed);
    }
  }, 16);
}

advanceStory() {
  const v = this.storyView;
  if (!v) return;
  if (v.mode === 'reply') { this.finishReply(); return; }
  if (v.mode !== 'dialogue') return;
  if (v.typing) {
    v.typing = false;
    clearInterval(this.typeTimer);
    $('storyText').textContent = v.text;
    $('storyText').classList.remove('typing');
    return;
  }
  v.line++;
  if (v.line >= v.mission.lines.length) this.afterDialogue();
  else { this.audio?.click(); this.renderStoryLine(); }
}

afterDialogue() {
  const v = this.storyView;
  if (!v) return;
  this.game.markStorySeen();
  if (v.mission.choice) { this.showStoryChoice(v.mission.choice); return; }
  this.showStorySummary(v.mission);
}

showStoryChoice(choice) {
  const v = this.storyView;
  if (!v) return;
  v.mode = 'choice';
  $('storyText').textContent = '';
  $('storySpeaker').textContent = 'DECISION';
  $('storyDots').innerHTML = '';
  $('storyNext').style.visibility = 'hidden';
  $('storyChoices').innerHTML = `<div class="choice-prompt">${choice.prompt}</div><div class="story-choice">${choice.options.map((o, i) => `<button class="choice-btn" data-act="storyChoice" data-index="${i}"><b>${o.label}</b><span>${o.sub || ''}</span></button>`).join('')}</div>`;
}

applyChoiceEffects(effects = {}) {
  const g = this.game, s = g.state;
  if (effects.dirty) s.dirty = Math.max(0, s.dirty + effects.dirty);
  if (effects.clean) s.clean = Math.max(0, s.clean + effects.clean);
  if (effects.heat) s.heat = clamp(s.heat + effects.heat, 0, 100);
  if (effects.rep) s.rep = clamp(s.rep + effects.rep, 0, 100);
  if (effects.flag) s.flags[effects.flag] = true;
  g.save();
}

chooseStory(index) {
  const v = this.storyView;
  if (!v || v.mode !== 'choice') return;
  const choice = v.mission.choice;
  const opt = choice?.options[index];
  if (!opt) return;
  this.applyChoiceEffects(opt.effects);
  this.audio?.click();
  if (opt.effects?.heat) this.toast(`Heat ${opt.effects.heat > 0 ? '+' : ''}${opt.effects.heat}%`, opt.effects.heat > 0 ? 'warn' : 'good');
  v.mode = 'reply';
  v.text = opt.reply || '';
  v.typed = 0; v.typing = true;
  $('storySpeaker').textContent = 'THE CITY';
  $('storySpeaker').style.opacity = '.65';
  $('storyText').className = 'story-text narrator typing';
  $('storyChoices').innerHTML = '';
  $('storyNext').style.visibility = 'visible';
  $('storyNext').innerHTML = `CONTINUE ${ico('arrow')}`;
  clearInterval(this.typeTimer);
  this.typeTimer = setInterval(() => {
    if (!this.storyView || this.storyView.mode !== 'reply') { clearInterval(this.typeTimer); return; }
    v.typed += 2;
    if (v.typed >= v.text.length) {
      v.typed = v.text.length; v.typing = false;
      $('storyText').textContent = v.text;
      $('storyText').classList.remove('typing');
      clearInterval(this.typeTimer);
    } else $('storyText').textContent = v.text.slice(0, v.typed);
  }, 16);
  if (v.speakerId !== 'narrator') { this.drawPortrait($('storyPortrait'), 'narrator'); v.lastSpeaker = 'narrator'; }
  $('storyName').textContent = 'The City';
  $('storyRole').textContent = 'Consequence';
}

finishReply() {
  const v = this.storyView;
  if (!v) return;
  if (v.typing) {
    clearInterval(this.typeTimer);
    v.typing = false;
    $('storyText').textContent = v.text;
    $('storyText').classList.remove('typing');
    return;
  }
  this.showStorySummary(v.mission);
}

showStorySummary(m) {
  if (!m) return;
  const g = this.game, p = g.missionProgress();
  const lastSpeaker = [...m.lines].reverse().find(l => l.s !== 'narrator')?.s || 'milo';
  this.storyView = { mode: 'summary', mission: m };
  const r = m.reward || {};
  const rewardChips = [
    r.dirty ? `<span class="chip gold">+${money(r.dirty)} dirty</span>` : '',
    r.clean ? `<span class="chip green">+${money(r.clean)} clean</span>` : '',
    r.rep ? `<span class="chip purple">+${r.rep} REP</span>` : '',
    r.heat ? `<span class="chip ${r.heat > 0 ? 'red' : 'green'}">${r.heat > 0 ? '+' : ''}${r.heat}% heat</span>` : ''
  ].filter(Boolean).join('');
  const html = `<div class="story-card">
    <button class="icon-btn story-close" data-act="storyClose" aria-label="Close story">${ico('close')}</button>
    <div class="story-portrait">
      <canvas id="storyPortrait" width="320" height="440"></canvas><div class="portrait-vignette"></div>
      <div class="portrait-name"><b>${CHARACTERS[lastSpeaker]?.name || 'Milo Vance'}</b><span>${CHARACTERS[lastSpeaker]?.role || ''}</span></div>
    </div>
    <div class="story-main">
      <div class="story-top"><div><div class="story-act">${m.act} · MISSION ${pad2(this.game.state.story.idx + 1)}</div><div class="story-place">${m.place}</div></div></div>
      <div class="story-title">${m.title}</div>
      <div class="story-dialogue">
        <div class="story-speaker">OBJECTIVE</div>
        <div class="objective-card">
          <div class="objective-top"><span>${p?.complete ? 'READY TO CLAIM' : 'IN PROGRESS'}</span><span>${Math.floor(p?.current || 0)} / ${p?.target || 1}</span></div>
          <div class="objective-label">${m.objective.label}</div>
          <div class="bar"><i style="width:${(p?.pct || 0) * 100}%;background:${p?.complete ? 'var(--acid)' : 'var(--green)'}"></i></div>
          <div class="reward-row">${rewardChips || '<span class="chip">Story reward</span>'}</div>
        </div>
      </div>
      <div class="story-foot">
        <button class="story-replay" data-act="storyReplay">REREAD BRIEFING</button>
        <div class="story-actions" style="margin:0;flex:0 0 auto">
          <button class="btn ghost" data-act="storyClose" style="flex:0 0 auto">${p?.complete ? 'LATER' : 'BACK TO WORK'}</button>
          ${p?.complete ? `<button class="btn" data-act="storyClaim">CLAIM REWARD</button>` : ''}
        </div>
      </div>
    </div>
  </div>`;
  this.setModal(html, 'story');
  this.drawPortrait($('storyPortrait'), lastSpeaker);
}

claimMission() {
  const g = this.game;
  const r = g.completeMission();
  if (!r.ok) { this.toast(r.msg || 'Not ready yet.', 'warn'); this.audio?.error(); return; }
  const rw = r.mission.reward || {};
  const parts = [];
  if (rw.dirty) parts.push(`+${money(rw.dirty)} dirty`);
  if (rw.clean) parts.push(`+${money(rw.clean)} clean`);
  if (rw.rep) parts.push(`+${rw.rep} REP`);
  if (rw.heat) parts.push(`${rw.heat > 0 ? '+' : ''}${rw.heat}% heat`);
  this.toast(`MISSION COMPLETE · ${r.mission.title}${parts.length ? ' · ' + parts.join(' · ') : ''}`, 'good');
  this.audio?.success();
  this.renderer.sparkleScreen();
  this.closeModal();
  if (r.ending) setTimeout(() => this.openEnding(), 500);
  else if (r.betrayal) setTimeout(() => this.openBetrayal(g.triggerBetrayal()), 700);
  else if (r.next) {
    setTimeout(() => this.toast(`New mission: ${r.next.title}`, 'info'), 900);
    setTimeout(() => this.openStory(), 1500);
  }
  this.syncStats(); this.syncMission();
}

openStoryComplete() {
  const g = this.game, s = g.state;
  this.storyView = { mode: 'summary' };
  this.setModal(`<div class="ending-card">
