331:     else if (act === 'pricing') { g.state.pricing = data.id; g.save(); this.refreshPanel(); }
332:     else if (act === 'replant') { g.replantAll(); this.refreshPanel(); }
333:     else if (act === 'buff') {
334:       const r = g.buyBuff(data.id);
335:       if (!r.ok) { this.toast(r.msg || 'Cannot buy that.', 'warn'); this.audio?.error(); }
336:       else { this.toast(`${r.b.name} active for 3 harvests.`, 'good'); this.refreshPanel(); }
337:     }
338:     else if (act === 'refine') { this.closePanel(); this.openRefine(data.id); }
339:     else if (act === 'hire') {
340:       const r = g.hireStaff(data.id);
341:       if (!r.ok) { this.toast(r.msg || 'Cannot hire.', 'warn'); this.audio?.error(); }
342:       else { this.toast(`${r.staff.name} joined the crew.`, 'good'); this.audio?.success(); this.renderer.sparkleScreen(); this.refreshPanel(); }
343:     }
344:     else if (act === 'upgrade') {
345:       const r = g.buyUpgrade(g.state.activeProperty, data.id);
346:       if (!r.ok) { this.toast(r.msg || 'Cannot upgrade.', 'warn'); this.audio?.error(); }
347:       else { this.toast(`${UPGRADE_BY_ID[data.id].name} upgraded.`, 'good'); this.audio?.success(); this.refreshPanel(); }
348:     }
349:     else if (act === 'buyprop') {
350:       const r = g.buyProperty(data.id);
351:       if (!r.ok) { this.toast(r.msg || 'Cannot buy.', 'warn'); this.audio?.error(); }
352:       else { this.toast(r.moved ? `Moved to ${PROPERTIES[data.id].name}.` : `Bought ${PROPERTIES[data.id].name}.`, 'good'); this.audio?.success(); this.renderer.sparkleScreen(); this.renderer.resize(); this.refreshPanel(); }
353:     }
354:     else if (act === 'visit') { g.moveProperty(data.id); this.toast(`Moved to ${PROPERTIES[data.id].name}.`, 'info'); this.renderer.resize(); this.refreshPanel(); }
355:     else if (act === 'launder') {
356:       const r = g.launder(data.amount === 'all' ? 'all' : Number(data.amount));
357:       if (!r.ok) { this.toast(r.msg || 'Cannot launder.', 'warn'); this.audio?.error(); }
358:       else { this.toast(`Washed ${money(r.amount)} → ${money(r.cleanGain)} clean.`, 'good'); this.audio?.cash(); this.refreshPanel(); }
359:     }
360:     else if (act === 'front') {
361:       const r = g.buyFront(data.id);
362:       if (!r.ok) { this.toast(r.msg || 'Cannot buy front.', 'warn'); this.audio?.error(); }
363:       else { this.toast(`${r.f.name} acquired. The money has a porch now.`, 'good'); this.audio?.success(); this.renderer.sparkleScreen(); this.refreshPanel(); }
364:     }
365:     else if (act === 'bribe') {
366:       const r = g.bribe();
367:       if (!r.ok) { this.toast(r.msg || 'No one is buying.', 'warn'); this.audio?.error(); }
368:       else { this.toast(`Bribed the precinct. Heat -26%.`, 'good'); this.audio?.cash(); this.refreshPanel(); }
369:     }
370:     else if (act === 'laylow') {
371:       g.layLow(50);
372:       this.toast('Lights out for 50 seconds. No customers, less heat.', 'info');
373:       this.refreshPanel();
374:     }
375:     else if (act === 'settingsSound') { this.toggleSound(); this.refreshPanel(); }
376:     else if (act === 'settingsHints') { g.state.settings.hints = !g.state.settings.hints; g.save(); this.refreshPanel(); }
377:     else if (act === 'save') { g.save(); this.toast('Empire saved locally.', 'good'); this.audio?.success(); }
378:     else if (act === 'reset1') { this.confirmReset = true; this.refreshPanel(); }
379:     else if (act === 'reset2') {
380:       g.save();
381:       localStorage.removeItem('greenEmpire.save.v2');
382:       g.freshStart();
383:       this.closePanel();
384:       location.reload();
385:     }
