function frame(now) {
  const dt = Math.min(Math.max(0, (now - last) / 1000), 0.05);
  last = now;

  if (ui.splashDone) game.update(dt);
  renderer.draw(dt);
  ui.sync(dt);

  requestAnimationFrame(frame);
}
