49:     this.runtime.raidCooldown = 0;
50:     this.runtime.pendingEvent = null;
51:     this.save();
52:     this.emit('newgame');
53:   }
54: 
55:   load() {
56:     try {
57:       const raw = localStorage.getItem(SAVE_KEY);
58:       if (!raw) return false;
59:       const data = JSON.parse(raw);
60:       if (!data || data.version !== 2) return false;
61:       const base = this.newState();
62:       this.state = { ...base, ...data, settings: { ...base.settings, ...data.settings }, story: { ...base.story, ...data.story }, stats: { ...base.stats, ...data.stats } };
63:       // hydrate property slots defensively
64:       for (const p of PROPERTY_LIST) {
65:         if (!this.state.properties[p.id]) this.state.properties[p.id] = base.properties[p.id];
66:         const ps = this.state.properties[p.id];
67:         ps.upgrades = { ...base.properties[p.id].upgrades, ...ps.upgrades };
68:         if (!Array.isArray(ps.slots)) ps.slots = p.slots.map(() => null);
69:         while (ps.slots.length < p.slots.length) ps.slots.push(null);
70:       }
71:       this.state.inventory = data.inventory || {};
72:       this.state.flags = data.flags || {};
73:       const away = Math.max(0, (Date.now() - (data.lastSave || Date.now())) / 1000);
74:       const summary = this.simulateOffline(away);
75:       this.runtime.lastLoadSummary = summary;
76:       return true;
77:     } catch (err) {
78:       console.warn('Save load failed', err);
79:       return false;
80:     }
81:   }
82: 
83:   save() {
84:     this.state.lastSave = Date.now();
85:     try { localStorage.setItem(SAVE_KEY, JSON.stringify(this.state)); } catch {}
86:   }
87: 
88:   simulateOffline(seconds) {
89:     if (!seconds || seconds < 8) return null;
90:     const sec = Math.min(seconds, 4 * 3600);
91:     const before = { dirty: this.state.dirty, clean: this.state.clean };
92:     this.state.clock += sec;
93:     this.state.heat = Math.max(0, this.state.heat - sec * 0.1);
94:     this.state.dayTime += sec;
95:     while (this.state.dayTime >= DAY_LENGTH) { this.state.dayTime -= DAY_LENGTH; this.state.day++; }
96:     let ready = 0, grown = 0;
97:     for (const p of PROPERTY_LIST) {
98:       const ps = this.state.properties[p.id];
99:       if (!ps?.owned) continue;
100:       ps.slots.forEach((slot, i) => {
101:         if (!slot) return;
102:         const strain = STRAIN_BY_ID[slot.strain];
103:         if (!strain) return;
104:         if (slot.progress < 1) {
105:           const rate = this.growthRate(p.id, slot);
106:           slot.progress = Math.min(1, slot.progress + rate * sec);
107:           grown++;
108:         }
109:         if (slot.progress >= 1 && slot.notified !== true) { slot.notified = true; ready++; }
110:       });
111:     }
112:     // fronts quietly wash money while away
113:     let washed = 0;
114:     for (const id of this.state.fronts) {
115:       const f = FRONT_BY_ID[id];
116:       if (!f || !f.rate) continue;
117:       const amount = Math.min(this.state.dirty, (f.rate / 60) * Math.min(sec, 2 * 3600));
118:       if (amount <= 0) continue;
119:       this.state.dirty -= amount;
120:       this.state.clean += amount * f.conv;
121:       this.state.stats.laundered += amount;
122:       washed += amount * f.conv;
123:     }
124:     return { seconds: sec, ready, grown, washed: Math.floor(washed), dirtyDelta: Math.floor(this.state.dirty - before.dirty), cleanDelta: Math.floor(this.state.clean - before.clean) };
125:   }
126: 
127:   // ---------- events ----------
128:   on(evt, fn) {
129:     if (!this.listeners.has(evt)) this.listeners.set(evt, []);
130:     this.listeners.get(evt).push(fn);
131:     return () => { const arr = this.listeners.get(evt) || []; const i = arr.indexOf(fn); if (i >= 0) arr.splice(i, 1); };
132:   }
133:   emit(evt, data) {
134:     for (const fn of this.listeners.get(evt) || []) { try { fn(data); } catch (e) { console.error(e); } }
135:   }
136:   toast(text, kind = 'info') { this.emit('toast', { text, kind }); }
137: 
138:   // ---------- helpers ----------
139:   get propConfig() { return PROPERTIES[this.state.activeProperty] || PROPERTIES.apartment; }
140:   get propState() { return this.state.properties[this.state.activeProperty]; }
141:   get mission() { return MISSIONS[this.state.story.idx] || null; }
142:   get hour() { return (8 + (this.state.dayTime / DAY_LENGTH) * 24) % 24; }
143:   get isNight() { const h = this.hour; return h < 6.2 || h > 19.5; }
144:   get totalCash() { return this.state.dirty + this.state.clean; }
145:   get wageTotal() { return this.state.staff.reduce((n, id) => n + (STAFF_BY_ID[id]?.wage || 0), 0); }
146:   get layLowActive() { return this.state.layLowUntil > this.state.clock; }
147:   get heatGainMult() {
148:     const sec = this.propState?.upgrades?.security || 0;
149:     return (this.state.staff.includes('bruno') ? .75 : 1) * (1 - sec * .12);
150:   }
151: 
152:   rank() { return rankFor(this.state.rep); }
153: 
154:   strainUnlocked(id) {
155:     const s = STRAIN_BY_ID[id];
156:     if (!s) return false;
157:     return this.state.story.idx >= s.unlockedAt;
158:   }
159:   propertyAvailable(id) {
160:     const p = PROPERTIES[id];
161:     if (!p) return false;
162:     if (this.state.properties[id].owned) return true;
163:     return this.state.story.idx >= p.reqMission;
164:   }
165:   frontsUnlocked() { return this.state.story.idx >= 2; }
166:   staffUnlocked() { return this.state.story.idx >= 3; }
167: 
168:   stockGrams() {
169:     return Object.values(this.state.inventory).reduce((n, s) => n + (s?.g || 0), 0);
170:   }
171:   qualityAvg() {
172:     let total = 0, q = 0;
173:     for (const s of Object.values(this.state.inventory)) { if (!s?.g) continue; total += s.g; q += s.g * s.q; }
174:     return total ? q / total : 0;
175:   }
176:   strainStock(id) { return this.state.inventory[id]?.g || 0; }
177:   bestStock() {
178:     let best = null;
179:     for (const [id, lot] of Object.entries(this.state.inventory)) {
180:       if (!lot?.g) continue;
181:       const score = lot.g * (STRAIN_BY_ID[id]?.price || 1) * (0.55 + lot.q / 100 * .95);
182:       if (!best || score > best.score) best = { id, ...lot, score };
183:     }
184:     return best;
185:   }
186:   addStock(id, grams, quality) {
187:     if (grams <= 0) return;
188:     const cur = this.state.inventory[id];
189:     if (!cur) this.state.inventory[id] = { g: grams, q: quality };
190:     else {
191:       const total = cur.g + grams;
192:       cur.q = (cur.q * cur.g + quality * grams) / total;
193:       cur.g = total;
194:     }
195:   }
196:   removeStock(grams, id = null) {
197:     let left = grams;
198:     const order = id ? [id] : Object.keys(this.state.inventory).sort((a, b) => (this.state.inventory[b]?.g || 0) - (this.state.inventory[a]?.g || 0));
199:     for (const key of order) {
200:       const lot = this.state.inventory[key];
201:       if (!lot?.g) continue;
202:       const take = Math.min(lot.g, left);
203:       lot.g -= take; left -= take;
204:       if (lot.g <= 0.01) delete this.state.inventory[key];
205:       if (left <= 0.01) return true;
206:     }
207:     return left <= 0.01;
208:   }
209:   removeStockOf(id, grams) {
210:     const lot = this.state.inventory[id];
211:     if (!lot || lot.g < grams) return false;
212:     lot.g -= grams;
213:     if (lot.g <= 0.01) delete this.state.inventory[id];
214:     return true;
215:   }
216:   spendDirty(n) {
217:     if (n <= 0) return true;
218:     if (this.state.dirty < n) return false;
219:     this.state.dirty -= n;
220:     return true;
221:   }
222:   addDirty(n) { this.state.dirty += n; }
223:   addClean(n) { this.state.clean += n; }
224: 
225:   addBuff(id, charges = 3) {
226:     const b = BUFFS.find(x => x.id === id);
227:     if (!b) return;
228:     this.state.buff = { id, charges, type: b.type };
229:     this.emit('buff', b);
230:   }
231: 
232:   // ---------- growing ----------
233:   growthRate(propId, slot) {
234:     const p = PROPERTIES[propId];
235:     const ps = this.state.properties[propId];
236:     const strain = STRAIN_BY_ID[slot.strain];
237:     if (!p || !strain) return 0;
238:     const lights = ps.upgrades.lights || 0;
239:     let mult = 1 + lights * .12 + (p.growthMod || 0);
240:     if (this.state.buff?.type === 'speed') mult *= 1.4;
241:     return mult / strain.growTime;
242:   }
243: 
244:   plant(propId, index, strainId = this.state.selectedStrain) {
245:     const ps = this.state.properties[propId];
246:     const p = PROPERTIES[propId];
247:     const strain = STRAIN_BY_ID[strainId];
248:     if (!ps?.owned || !p) return { ok: false, msg: 'Property not owned.' };
249:     if (!strain) return { ok: false, msg: 'Unknown strain.' };
250:     if (!this.strainUnlocked(strainId)) return { ok: false, msg: 'That strain is still locked.' };
251:     const slot = ps.slots[index];
252:     if (slot) return { ok: false, msg: 'That pot is already growing.' };
253:     if (this.state.freePlantings > 0) this.state.freePlantings--;
254:     else if (!this.spendDirty(strain.cost)) return { ok: false, msg: `Need $${strain.cost} for a ${strain.short} seed.` };
255:     ps.slots[index] = { strain: strainId, progress: 0, tendQ: 0, lastTend: -99, planted: this.state.clock, notified: false };
256:     this.state.stats.plants++;
257:     this.emit('plant', { propId, index, strain: strainId });
258:     this.save();
259:     return { ok: true, strain };
260:   }
261: 
262:   selectedStrainId() {
263:     const id = this.state.selectedStrain;
264:     return this.strainUnlocked(id) ? id : 'dime';
265:   }
266:   selectStrain(id) {
267:     if (!this.strainUnlocked(id)) return this.toast('Unlock that strain through the story first.', 'warn');
268:     this.state.selectedStrain = id;
269:     this.emit('ui');
270:   }
271: 
272:   tend(propId, index) {
273:     const slot = this.state.properties[propId]?.slots[index];
274:     if (!slot || slot.progress >= 1) return { ok: false };
275:     if (this.state.clock - slot.lastTend < 4) return { ok: false, msg: 'Give it a moment to drink.' };
276:     slot.lastTend = this.state.clock;
277:     slot.progress = Math.min(1, slot.progress + .11);
278:     slot.tendQ = Math.min(12, (slot.tendQ || 0) + 1);
279:     this.emit('tend', { propId, index });
280:     return { ok: true };
281:   }
282: 
283:   harvest(propId, index, auto = false) {
284:     const ps = this.state.properties[propId];
285:     const p = PROPERTIES[propId];
286:     const slot = ps?.slots[index];
287:     if (!slot || slot.progress < 1) return null;
288:     const strain = STRAIN_BY_ID[slot.strain];
289:     if (!strain) { ps.slots[index] = null; return null; }
290:     const up = ps.upgrades;
291:     let quality = strain.quality + (p.qualityMod || 0) + up.vent * 4 + up.irrigation * 2 + (this.state.staff.includes('priya') ? 8 : 0) + (slot.tendQ || 0);
292:     if (this.state.buff?.type === 'quality') quality += 9;
293:     quality += rnd(-3, 3);
294:     quality = clamp(round(quality), 15, 100);
295:     let yieldG = strain.yield * (1 + (p.yieldMod || 0) + up.lights * .03) * rnd(.92, 1.08);
296:     if (this.state.buff?.type === 'yield') yieldG *= 1.25;
297:     yieldG = Math.max(1, round(yieldG));
298:     this.addStock(strain.id, yieldG, quality);
299:     this.state.stats.harvests++;
300:     this.state.stats.harvested += yieldG;
301:     if (this.state.buff) {
302:       this.state.buff.charges--;
303:       if (this.state.buff.charges <= 0) this.state.buff = null;
304:     }
305:     ps.slots[index] = null;
306:     this.emit('harvest', { propId, index, strain: strain.id, grams: yieldG, quality, auto });
307:     this.save();
308:     return { strain, grams: yieldG, quality };
309:   }
310: 
311:   replantAll(propId = this.state.activeProperty) {
312:     const ps = this.state.properties[propId];
313:     if (!ps?.owned) return;
314:     const strain = STRAIN_BY_ID[this.selectedStrainId()];
315:     let n = 0;
316:     ps.slots.forEach((slot, i) => {
317:       if (!slot && (this.state.dirty >= strain.cost || this.state.freePlantings > 0)) {
318:         const r = this.plant(propId, i, strain.id);
319:         if (r.ok) n++;
320:       }
321:     });
322:     if (n) this.toast(`Replanted ${n} ${strain.short} seed${n > 1 ? 's' : ''}.`, 'good');
323:     else this.toast('No empty pots or not enough cash.', 'warn');
324:   }
325: 
326:   // ---------- customers & sales ----------
327:   sellPrice(strainId, quality, multiplier = 1) {
328:     const strain = STRAIN_BY_ID[strainId];
329:     const p = this.propConfig;
330:     const up = this.propState.upgrades;
331:     const pricing = PRICING[this.state.pricing] || PRICING.standard;
332:     const qFactor = .55 + clamp(quality, 0, 100) / 100 * .95;
333:     const repFactor = .82 + clamp(this.state.rep, 0, 100) / 300;
334:     return strain.price * qFactor * (p.priceMod || 1) * (1 + (up.counter || 0) * .07) * pricing.mod * repFactor * multiplier;
335:   }
336: 
337:   customerOffer(c) {
338:     const stock = this.state.inventory[c.strain];
339:     const q = stock?.q || STRAIN_BY_ID[c.strain].quality;
340:     let unit = this.sellPrice(c.strain, q, c.type.mult);
341:     unit *= .94 + Math.random() * .12;
342:     return { unit, total: round(unit * c.grams), q };
343:   }
344: 
345:   spawnCustomer() {
346:     const freeQueue = [0, 1, 2, 3].filter(i => !this.runtime.customers.some(c => c.queueIndex === i && (c.state === 'wait' || c.state === 'enter')));
347:     if (!freeQueue.length) return;
348:     const qIndex = freeQueue[0];
349:     const available = STRAINS.filter(s => this.state.inventory[s.id]?.g > 0);
350:     let strainId;
351:     if (available.length && Math.random() < .78) strainId = available[Math.floor(Math.random() * available.length)].id;
352:     else {
353:       const unlocked = STRAINS.filter(s => this.strainUnlocked(s.id));
354:       strainId = unlocked[Math.floor(Math.random() * unlocked.length)].id;
355:     }
356:     const totalWeight = CUSTOMER_TYPES.reduce((n, t) => n + t.weight, 0);
357:     let roll = Math.random() * totalWeight, type = CUSTOMER_TYPES[0];
358:     for (const t of CUSTOMER_TYPES) { roll -= t.weight; if (roll <= 0) { type = t; break; } }
359:     const grams = Math.max(3, Math.min(15, 3 + Math.floor(Math.random() * 7) + Math.floor(this.state.rep / 22)));
360:     const prop = this.propConfig;
361:     const queue = prop.queue[qIndex] || [prop.counter[0], prop.counter[1] + 1.2];
362:     const c = {
363:       id: 'c' + Math.random().toString(36).slice(2, 8), type, strain: strainId, grams, queueIndex: qIndex,
364:       x: prop.door[0], y: prop.door[1], qx: queue[0], qy: queue[1],
365:       state: 'enter', patience: 0, maxPatience: rnd(30, 44), served: false, servedQty: 0,
366:       wobble: Math.random() * 6.28, created: this.state.clock
367:     };
368:     const offer = this.customerOffer(c);
369:     c.unit = offer.unit; c.total = offer.total; c.reqQ = offer.q;
370:     this.runtime.customers.push(c);
371:     this.emit('customer', c);
372:   }
373: 
374:   serveCustomer(c, auto = false) {
375:     if (!c || c.state !== 'wait' || c.served) return { ok: false };
376:     let strainId = c.strain;
377:     let lot = this.state.inventory[strainId];
378:     let substitute = false;
379:     if (!lot?.g) {
380:       const alt = this.bestStock();
381:       if (!alt) {
382:         if (!auto) this.toast('No product in stock. Harvest something first.', 'warn');
383:         return { ok: false, msg: 'Out of stock' };
384:       }
385:       strainId = alt.id; lot = { g: alt.g, q: alt.q }; substitute = true;
386:     }
387:     const qty = Math.min(c.grams, Math.floor(lot.g));
388:     if (qty <= 0) return { ok: false };
389:     const quality = lot.q;
390:     const unit = this.sellPrice(strainId, quality, c.type.mult) * (substitute ? .88 : 1);
391:     const payout = Math.max(1, round(unit * qty * (qty < c.grams ? .96 : 1)));
392:     this.removeStockOf(strainId, qty);
393:     this.addDirty(payout);
394:     this.state.stats.sold += qty;
395:     this.state.stats.earned += payout;
396:     this.state.stats.sales++;
397:     this.state.stats.bestSale = Math.max(this.state.stats.bestSale, payout);
398:     if (quality >= 70) this.state.stats.qualitySold += qty;
399:     const pricing = PRICING[this.state.pricing] || PRICING.standard;
400:     let repGain = (substitute ? .25 : .6) * pricing.rep * (qty < c.grams ? .5 : 1);
401:     this.state.rep = clamp(this.state.rep + repGain, 0, 100);
402:     const heatGain = (0.5 + qty * .05) * pricing.heat * this.heatGainMult * (1 + (this.propConfig.priceMod - 1) * .3);
403:     this.state.heat = clamp(this.state.heat + heatGain, 0, 100);
404:     c.served = true; c.servedQty = qty; c.state = 'leave'; c.target = this.propConfig.door;
405:     c.paid = payout;
406:     this.emit('sale', { customer: c, payout, qty, strainId, quality, auto, substitute });
407:     return { ok: true, payout, qty, quality, strainId };
408:   }
409: 
410:   autoServe() {
411:     const c = this.runtime.customers.find(x => x.state === 'wait' && !x.served);
412:     if (!c) return false;
413:     const r = this.serveCustomer(c, true);
414:     return r.ok;
415:   }
416: 
417:   quickSale(grams, mult = 1) {
418:     const lot = this.bestStock();
419:     if (!lot || lot.g < grams) return 0;
420:     const strainId = lot.id;
421:     const unit = this.sellPrice(strainId, lot.q, mult);
422:     const payout = Math.max(1, round(unit * grams));
423:     this.removeStockOf(strainId, grams);
424:     this.addDirty(payout);
425:     this.state.stats.sold += grams;
426:     this.state.stats.earned += payout;
427:     this.state.stats.sales++;
428:     if (lot.q >= 70) this.state.stats.qualitySold += grams;
429:     this.emit('sale', { payout, qty: grams, strainId, quality: lot.q, quick: true });
430:     return payout;
431:   }
432: 
433:   updateCustomers(dt) {
434:     const prop = this.propConfig;
435:     for (const c of this.runtime.customers) {
436:       if (c.state === 'enter') {
437:         const dx = c.qx - c.x, dy = c.qy - c.y, dist = Math.hypot(dx, dy);
438:         if (dist < .12) { c.x = c.qx; c.y = c.qy; c.state = 'wait'; c.patience = c.maxPatience; }
439:         else { c.x += dx / dist * 1.7 * dt; c.y += dy / dist * 1.7 * dt; c.wobble += dt * 7; }
440:       } else if (c.state === 'wait') {
441:         c.patience -= dt;
442:         c.wobble += dt * 2;
443:         if (c.patience <= 0) {
444:           c.state = 'leave'; c.target = prop.door;
445:           this.state.rep = clamp(this.state.rep - .9, 0, 100);
446:           this.emit('angry', { customer: c });
447:         }
448:       } else if (c.state === 'leave') {
449:         const dx = prop.door[0] - c.x, dy = prop.door[1] - c.y, dist = Math.hypot(dx, dy);
450:         if (dist < .2) c.dead = true;
451:         else { c.x += dx / dist * 2.1 * dt; c.y += dy / dist * 2.1 * dt; c.wobble += dt * 9; }
452:       }
453:     }
454:     this.runtime.customers = this.runtime.customers.filter(c => !c.dead);
455:   }
456: 
457:   // ---------- main loop ----------
458:   update(dt) {
459:     dt = Math.min(dt || 0, .5);
460:     const s = this.state;
461:     s.clock += dt;
462:     s.stats.played += dt;
463:     const paused = this.runtime.uiPaused || this.runtime.pendingEvent;
464: 
465:     // plants grow in every owned property
466:     for (const p of PROPERTY_LIST) {
467:       const ps = s.properties[p.id];
468:       if (!ps?.owned) continue;
469:       ps.slots.forEach(slot => {
470:         if (!slot || slot.progress >= 1) return;
471:         slot.progress = Math.min(1, slot.progress + this.growthRate(p.id, slot) * dt);
472:         if (slot.progress >= 1 && !slot.notified) {
473:           slot.notified = true;
474:           if (p.id === s.activeProperty) this.emit('ready', { propId: p.id, slot });
475:         }
476:       });
477:     }
478: 
479:     // active room customers
480:     if (!paused) {
481:       this.updateCustomers(dt);
482:       this.runtime.spawnTimer -= dt;
483:       if (this.runtime.spawnTimer <= 0 && !this.layLowActive && s.heat < 96) {
484:         this.spawnCustomer();
485:         const busy = this.runtime.customers.filter(c => c.state === 'wait' || c.state === 'enter').length;
486:         const base = clamp(9.5 - s.rep / 16 - PROPERTY_LIST.findIndex(x => x.id === s.activeProperty) * .5 + (s.heat > 60 ? 2 : 0) + busy * .8, 3.2, 11);
487:         this.runtime.spawnTimer = base * rnd(.85, 1.2);
488:       }
489:       // staff automation
490:       this.updateStaff(dt);
491:       // random events
492:       this.runtime.eventTimer -= dt;
493:       if (this.runtime.eventTimer <= 0 && s.story.idx >= 1 && !this.runtime.pendingEvent) {
494:         this.triggerRandomEvent();
495:         this.runtime.eventTimer = rnd(80, 130);
496:       }
497:     }
498: 
499:     // fronts: passive laundering + heat relief
500:     this.updateFronts(dt);
501: 
502:     // heat cools slowly, security and lawyer help
503:     const cooling = .1 + (s.fronts.includes('legal') ? .2 : 0) + this.propState.upgrades.security * .02;
504:     s.heat = Math.max(0, s.heat - cooling * dt);
505: 
506:     // day clock
507:     s.dayTime += dt;
508:     if (s.dayTime >= DAY_LENGTH) {
509:       s.dayTime -= DAY_LENGTH;
