import { createRequire } from 'node:module';
import { join } from 'node:path';
import { readFileSync, mkdirSync } from 'node:fs';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions });
const page = await browser.newPage({ viewport: { width: 1200, height: 800 }, deviceScaleFactor: 1 });
const errors = [];
const failed = [];
page.on('pageerror', e => errors.push(e.stack || e.message));
page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
page.on('requestfailed', r => failed.push(`${r.url()} ${r.failure()?.errorText}`));
page.on('response', r => { if (r.status() >= 400) failed.push(`${r.status()} ${r.url()}`); });
await page.goto('http://127.0.0.1:3000/', { waitUntil: 'networkidle' });
await page.locator('#btnStart').click();
await page.waitForTimeout(300);
const result = await page.evaluate(() => {
  const { game, ui } = window.__GREEN_EMPIRE__;
  const saveKey = 'greenEmpire.save.v2';
  const initialStoredSave = localStorage.getItem(saveKey);
  game.freshStart();
  ui.splashDone = true;
  game.setPaused(false);
  if (ui.modalType) ui.closeModal();

  const firstPlant = game.plant('apartment', 0, 'dime');
  game.state.properties.apartment.slots[0].progress = 1;
  const firstHarvest = game.harvest('apartment', 0);
  const firstObjective = game.missionProgress();
  const firstClaim = game.completeMission();

  const secondPlants = [0, 1, 2].map(i => game.plant('apartment', i, 'dime'));
  for (let i = 0; i < 3; i++) game.state.properties.apartment.slots[i].progress = 1;
  const secondHarvests = [0, 1, 2].map(i => game.harvest('apartment', i));
  const stockBeforeSale = game.stockGrams();
  const salePayout = game.quickSale(20);
  const saleObjective = game.missionProgress();
  const secondClaim = game.completeMission();
  game.save();
  const savedRaw = localStorage.getItem(saveKey);
  const saved = savedRaw ? JSON.parse(savedRaw) : null;

  // Disturb in-memory progress, then use the game's real loader to prove the saved state is restored.
  game.state.story.idx = 0;
  game.state.stats.sold = 0;
  const loaded = game.load();
  const persistence = {
    key: saveKey,
    saved: !!savedRaw,
    savedVersion: saved?.version,
    savedMissionIndex: saved?.story?.idx,
    savedSoldGrams: saved?.stats?.sold,
    loadSucceeded: loaded,
    restoredMissionIndex: game.state.story.idx,
    restoredSoldGrams: game.state.stats.sold
  };

  // Leave the test browser's storage as it was found; this is a fresh isolated browser context.
  if (initialStoredSave === null) localStorage.removeItem(saveKey);
  else localStorage.setItem(saveKey, initialStoredSave);
  ui.sync(0, true);
  if (ui.modalType) ui.closeModal();
  ui.sync(0, true);
  return {
    firstPlant: firstPlant.ok,
    firstHarvestGrams: firstHarvest?.grams,
    firstObjectiveComplete: firstObjective?.complete,
    firstMissionClaimed: firstClaim.ok,
    secondPlantsSucceeded: secondPlants.every(p => p.ok),
    secondHarvestGrams: secondHarvests.map(h => h?.grams),
    stockBeforeSale,
    salePayout,
    saleObjective: saleObjective && { current: saleObjective.current, target: saleObjective.target, complete: saleObjective.complete },
    secondMissionClaimed: secondClaim.ok,
    persisted: persistence
  };
});
await page.waitForTimeout(400);
mkdirSync('/home/runner/work/PlayGround/PlayGround/screenshots', { recursive: true });
await page.screenshot({ path: '/home/runner/work/PlayGround/PlayGround/screenshots/latest-verification.jpg', type: 'jpeg', quality: 78 });
console.log(JSON.stringify({ result, errors, failed, screenshot: 'screenshots/latest-verification.jpg', viewport: page.viewportSize() }, null, 2));
await browser.close();
EOF
